/**
 * Converts normalized touch samples into named player actions.
 */
import type { DiscretePlayerActionType, PlayerAction } from "../core/actions";
import {
  createHorizontalDragAction,
  createHorizontalDragEndAction,
  createPlayerAction
} from "../core/actions";

/** Gesture thresholds locked by the UX spec. */
export interface GestureThresholds {
  readonly swipeMinDistancePt: number;
  readonly swipeMinVelocityPtPerSec: number;
  readonly tapMaxMovementPt: number;
  readonly tapMaxDurationMs: number;
  readonly swipeDirectionToleranceDeg: number;
  readonly hardDropVelocityPtPerSec: number;
}

/** Normalized touch sample independent of DOM TouchEvent objects. */
export interface TouchSample {
  readonly id: number;
  readonly xPt: number;
  readonly yPt: number;
  readonly timeMs: number;
}

/** Gesture recognizer contract for Phase 5 implementation. */
export interface GestureRecognizer {
  setHorizontalCellSizePt(cellSizePt: number, timeMs?: number): readonly PlayerAction[];
  start(samples: readonly TouchSample[]): readonly PlayerAction[];
  move(samples: readonly TouchSample[]): readonly PlayerAction[];
  end(samples: readonly TouchSample[]): readonly PlayerAction[];
  cancel(timeMs?: number): readonly PlayerAction[];
}

/** Optional recognizer configuration. */
export interface GestureRecognizerOptions {
  readonly thresholds?: GestureThresholds;
  readonly horizontalCellSizePt?: number;
}

export const GESTURE_THRESHOLDS: GestureThresholds = {
  swipeMinDistancePt: 20,
  swipeMinVelocityPtPerSec: 200,
  tapMaxMovementPt: 10,
  tapMaxDurationMs: 250,
  swipeDirectionToleranceDeg: 30,
  hardDropVelocityPtPerSec: 600
};

const DEFAULT_HORIZONTAL_CELL_SIZE_PT = 32;
const CELL_SIZE_CHANGE_EPSILON_PT = 0.001;

interface TrackedTouch {
  readonly start: TouchSample;
  current: TouchSample;
}

interface HorizontalDrag {
  readonly touchId: number;
  readonly gestureId: number;
  readonly cellSizePt: number;
  lastOffsetColumns: number;
}

/** Creates the touch gesture recognizer. */
export function createGestureRecognizer(options: GestureRecognizerOptions = {}): GestureRecognizer {
  const thresholds = options.thresholds ?? GESTURE_THRESHOLDS;
  const touches = new Map<number, TrackedTouch>();
  const endedTouches = new Set<number>();
  let horizontalCellSizePt =
    options.horizontalCellSizePt === undefined
      ? DEFAULT_HORIZONTAL_CELL_SIZE_PT
      : normalizeRuntimeCellSize(options.horizontalCellSizePt);
  let nextGestureId = 1;
  let gestureRecognized = false;
  let gestureCompleted = false;
  let softDropActive = false;
  let horizontalDrag: HorizontalDrag | null = null;

  function reset(): void {
    touches.clear();
    endedTouches.clear();
    gestureRecognized = false;
    gestureCompleted = false;
    softDropActive = false;
    horizontalDrag = null;
  }

  function applySamples(samples: readonly TouchSample[], allowNewTouches: boolean): void {
    for (const sample of samples) {
      const existing = touches.get(sample.id);
      if (existing) {
        existing.current = sample;
      } else if (allowNewTouches) {
        touches.set(sample.id, { start: sample, current: sample });
      }
    }
  }

  function getTrackedTouch(id: number): TrackedTouch | null {
    return touches.get(id) ?? null;
  }

  function getPrimaryTouch(): TrackedTouch | null {
    for (const touch of touches.values()) {
      return touch;
    }
    return null;
  }

  function latestKnownTimeMs(): number {
    let latest = 0;
    for (const touch of touches.values()) {
      latest = Math.max(latest, touch.start.timeMs, touch.current.timeMs);
    }
    return latest;
  }

  function emit(type: DiscretePlayerActionType, occurredAtMs: number): PlayerAction {
    return createPlayerAction(type, occurredAtMs);
  }

  function beginHorizontalDrag(touch: TrackedTouch): readonly PlayerAction[] {
    if (horizontalCellSizePt <= 0) {
      return [];
    }

    horizontalDrag = {
      touchId: touch.start.id,
      gestureId: nextGestureId,
      cellSizePt: horizontalCellSizePt,
      lastOffsetColumns: 0
    };
    nextGestureId += 1;
    gestureRecognized = true;
    return collectHorizontalDragUpdate(horizontalDrag, touch);
  }

  function collectHorizontalDragUpdate(drag: HorizontalDrag, touch: TrackedTouch): readonly PlayerAction[] {
    const offsetColumns = roundedHorizontalOffsetColumns(touch, drag.cellSizePt);
    if (offsetColumns === drag.lastOffsetColumns) {
      return [];
    }

    drag.lastOffsetColumns = offsetColumns;
    return [createHorizontalDragAction(drag.gestureId, offsetColumns, touch.current.timeMs)];
  }

  function collectHorizontalDragEnd(drag: HorizontalDrag, occurredAtMs: number): readonly PlayerAction[] {
    return [createHorizontalDragEndAction(drag.gestureId, occurredAtMs)];
  }

  function recognizeMovement(touch: TrackedTouch): readonly PlayerAction[] {
    const dxPt = touch.current.xPt - touch.start.xPt;
    const dyPt = touch.current.yPt - touch.start.yPt;
    const distancePt = Math.hypot(dxPt, dyPt);
    if (distancePt <= thresholds.tapMaxMovementPt) {
      return [];
    }

    const absDxPt = Math.abs(dxPt);
    const absDyPt = Math.abs(dyPt);
    const horizontalAngleDeg = radiansToDegrees(Math.atan2(absDyPt, absDxPt));
    const verticalAngleDeg = radiansToDegrees(Math.atan2(absDxPt, absDyPt));

    if (horizontalAngleDeg <= thresholds.swipeDirectionToleranceDeg && absDxPt >= absDyPt) {
      return beginHorizontalDrag(touch);
    }

    if (dyPt > 0 && verticalAngleDeg <= thresholds.swipeDirectionToleranceDeg && absDyPt >= absDxPt) {
      const elapsedMs = touch.current.timeMs - touch.start.timeMs;
      const velocityPtPerSec = elapsedMs <= 0 ? Infinity : distancePt / (elapsedMs / 1000);
      if (
        distancePt < thresholds.swipeMinDistancePt ||
        velocityPtPerSec < thresholds.swipeMinVelocityPtPerSec
      ) {
        return [];
      }

      gestureRecognized = true;
      if (velocityPtPerSec >= thresholds.hardDropVelocityPtPerSec) {
        gestureCompleted = true;
        return [emit("hard-drop", touch.current.timeMs)];
      }

      softDropActive = true;
      return [emit("soft-drop-start", touch.current.timeMs)];
    }

    return [];
  }

  function collectTapActions(occurredAtMs: number): readonly PlayerAction[] {
    if (touches.size !== 1 && touches.size !== 2) {
      return [];
    }

    for (const touch of touches.values()) {
      const durationMs = touch.current.timeMs - touch.start.timeMs;
      if (
        durationMs > thresholds.tapMaxDurationMs ||
        pointDistance(touch.start, touch.current) > thresholds.tapMaxMovementPt
      ) {
        return [];
      }
    }

    return [emit(touches.size === 1 ? "rotate-cw" : "rotate-ccw", occurredAtMs)];
  }

  function allTouchesEnded(): boolean {
    return touches.size > 0 && endedTouches.size >= touches.size;
  }

  return {
    setHorizontalCellSizePt(cellSizePt: number, timeMs?: number): readonly PlayerAction[] {
      const nextCellSizePt = normalizeRuntimeCellSize(cellSizePt);
      if (Math.abs(nextCellSizePt - horizontalCellSizePt) <= CELL_SIZE_CHANGE_EPSILON_PT) {
        horizontalCellSizePt = nextCellSizePt;
        return [];
      }

      horizontalCellSizePt = nextCellSizePt;
      if (!horizontalDrag) {
        return [];
      }

      const actions = collectHorizontalDragEnd(horizontalDrag, timeMs ?? latestKnownTimeMs());
      reset();
      return actions;
    },

    start(samples: readonly TouchSample[]): readonly PlayerAction[] {
      if (touches.size === 0 || gestureCompleted) {
        reset();
      }
      applySamples(samples, true);
      if (horizontalDrag && touches.size !== 1) {
        const actions = collectHorizontalDragEnd(horizontalDrag, latestKnownTimeMs());
        reset();
        return actions;
      }
      return [];
    },

    move(samples: readonly TouchSample[]): readonly PlayerAction[] {
      if (touches.size === 0 || gestureCompleted) {
        return [];
      }

      applySamples(samples, false);
      if (horizontalDrag) {
        if (touches.size !== 1) {
          const actions = collectHorizontalDragEnd(horizontalDrag, latestSampleTimeMs(samples));
          reset();
          return actions;
        }

        const draggedTouch = getTrackedTouch(horizontalDrag.touchId);
        return draggedTouch ? collectHorizontalDragUpdate(horizontalDrag, draggedTouch) : [];
      }

      if (gestureRecognized || touches.size !== 1) {
        return [];
      }

      const touch = getPrimaryTouch();
      return touch ? recognizeMovement(touch) : [];
    },

    end(samples: readonly TouchSample[]): readonly PlayerAction[] {
      applySamples(samples, false);
      for (const sample of samples) {
        endedTouches.add(sample.id);
      }

      const occurredAtMs = samples.length > 0 ? latestSampleTimeMs(samples) : latestKnownTimeMs();
      const actions: PlayerAction[] = [];

      if (horizontalDrag) {
        actions.push(...collectHorizontalDragEnd(horizontalDrag, occurredAtMs));
      } else if (softDropActive) {
        actions.push(emit("soft-drop-stop", occurredAtMs));
      } else if (!gestureRecognized && !gestureCompleted && allTouchesEnded()) {
        actions.push(...collectTapActions(occurredAtMs));
      }

      if (allTouchesEnded() || gestureCompleted || softDropActive || horizontalDrag) {
        reset();
      }

      return actions;
    },

    cancel(timeMs?: number): readonly PlayerAction[] {
      const occurredAtMs = timeMs ?? latestKnownTimeMs();
      const actions = softDropActive
        ? [emit("soft-drop-stop", occurredAtMs)]
        : horizontalDrag
          ? collectHorizontalDragEnd(horizontalDrag, occurredAtMs)
          : [];
      reset();
      return actions;
    }
  };
}

function roundedHorizontalOffsetColumns(touch: TrackedTouch, cellSizePt: number): number {
  if (cellSizePt <= 0) {
    return 0;
  }

  const dxPt = touch.current.xPt - touch.start.xPt;
  const magnitude = Math.floor(Math.abs(dxPt / cellSizePt) + 0.5);
  return dxPt < 0 ? -magnitude : magnitude;
}

function normalizeRuntimeCellSize(cellSizePt: number): number {
  if (!Number.isFinite(cellSizePt) || cellSizePt <= 0) {
    return 0;
  }

  return cellSizePt;
}

function pointDistance(start: TouchSample, end: TouchSample): number {
  return Math.hypot(end.xPt - start.xPt, end.yPt - start.yPt);
}

function latestSampleTimeMs(samples: readonly TouchSample[]): number {
  let latest = 0;
  for (const sample of samples) {
    latest = Math.max(latest, sample.timeMs);
  }
  return latest;
}

function radiansToDegrees(value: number): number {
  return value * (180 / Math.PI);
}
