/**
 * Loads the required neon-glass visual theme assets before gameplay starts.
 */

/** Runtime image keys used by the Canvas renderer. */
export type NeonThemeImageKey =
  | "portraitBackground"
  | "desktopBackground"
  | "neonCells"
  | "hudPanel"
  | "previewSlot"
  | "tableRow"
  | "lineClear"
  | "tetrisBurst";

/** Immutable image asset snapshot for renderer use and diagnostics. */
export interface NeonThemeImageAsset {
  readonly key: NeonThemeImageKey;
  readonly src: string;
  readonly image: HTMLImageElement;
}

/** Failure detail for one required visual asset. */
export interface NeonThemeAssetLoadFailure {
  readonly key: NeonThemeImageKey;
  readonly src: string;
  readonly reason: string;
}

/** Contract consumed by theme-aware renderers. */
export interface NeonThemeAssets {
  getImage(key: NeonThemeImageKey): HTMLImageElement;
  snapshot(): readonly NeonThemeImageAsset[];
  dispose(): void;
}

/** Options for constructing a theme asset registry. */
export interface NeonThemeAssetOptions {
  readonly baseUrl?: string;
  readonly imageFactory?: () => HTMLImageElement;
}

/** Error thrown when any required theme asset fails to load. */
export class NeonThemeAssetLoadError extends Error {
  readonly failures: readonly NeonThemeAssetLoadFailure[];

  constructor(failures: readonly NeonThemeAssetLoadFailure[]) {
    const summary = failures.map((failure) => `${failure.key} (${failure.src})`).join(", ");
    super(`Required visual assets failed to load: ${summary}`);
    this.name = "NeonThemeAssetLoadError";
    this.failures = failures;
  }
}

const DEFAULT_BASE_URL = "./assets/theme/neon-glass/";

const THEME_IMAGE_PATHS: Readonly<Record<NeonThemeImageKey, string>> = {
  portraitBackground: "backgrounds/portrait-stage.png",
  desktopBackground: "backgrounds/desktop-stage.png",
  neonCells: "blocks/neon-cells.svg",
  hudPanel: "ui/hud-panel.svg",
  previewSlot: "ui/preview-slot.svg",
  tableRow: "ui/table-row.svg",
  lineClear: "effects/line-clear-strip.svg",
  tetrisBurst: "effects/tetris-burst.svg"
};

/** Returns the URL map for all required neon theme assets. */
export function getNeonThemeAssetUrls(baseUrl = DEFAULT_BASE_URL): Readonly<Record<NeonThemeImageKey, string>> {
  const normalizedBase = baseUrl.endsWith("/") ? baseUrl : `${baseUrl}/`;
  return {
    portraitBackground: `${normalizedBase}${THEME_IMAGE_PATHS.portraitBackground}`,
    desktopBackground: `${normalizedBase}${THEME_IMAGE_PATHS.desktopBackground}`,
    neonCells: `${normalizedBase}${THEME_IMAGE_PATHS.neonCells}`,
    hudPanel: `${normalizedBase}${THEME_IMAGE_PATHS.hudPanel}`,
    previewSlot: `${normalizedBase}${THEME_IMAGE_PATHS.previewSlot}`,
    tableRow: `${normalizedBase}${THEME_IMAGE_PATHS.tableRow}`,
    lineClear: `${normalizedBase}${THEME_IMAGE_PATHS.lineClear}`,
    tetrisBurst: `${normalizedBase}${THEME_IMAGE_PATHS.tetrisBurst}`
  };
}

/** Loads every required neon theme asset, failing startup if any image is unavailable. */
export async function loadNeonThemeAssets(options: NeonThemeAssetOptions = {}): Promise<NeonThemeAssets> {
  const urls = getNeonThemeAssetUrls(options.baseUrl);
  const imageFactory = options.imageFactory ?? getDefaultImageFactory();

  if (!imageFactory) {
    throw new NeonThemeAssetLoadError(
      (Object.keys(urls) as NeonThemeImageKey[]).map((key) => ({
        key,
        src: urls[key],
        reason: "Browser Image API unavailable"
      }))
    );
  }

  const settled = await Promise.all(
    (Object.keys(urls) as NeonThemeImageKey[]).map(async (key): Promise<LoadedThemeAssetResult> => {
      const src = urls[key];
      try {
        const image = await loadImage(key, src, imageFactory);
        return {
          ok: true,
          asset: { key, src, image }
        };
      } catch (error) {
        return {
          ok: false,
          failure: {
            key,
            src,
            reason: error instanceof Error ? error.message : "Image load failed"
          }
        };
      }
    })
  );

  const failures = settled.filter(isFailedAssetResult).map((result) => result.failure);
  if (failures.length > 0) {
    throw new NeonThemeAssetLoadError(failures);
  }

  return createLoadedThemeAssets(settled.filter(isLoadedAssetResult).map((result) => result.asset));
}

type LoadedThemeAssetResult =
  | { readonly ok: true; readonly asset: NeonThemeImageAsset }
  | { readonly ok: false; readonly failure: NeonThemeAssetLoadFailure };

function loadImage(
  key: NeonThemeImageKey,
  src: string,
  imageFactory: () => HTMLImageElement
): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = imageFactory();

    image.onload = (): void => {
      resolve(image);
    };
    image.onerror = (): void => {
      reject(new Error(`Image failed to load for ${key}`));
    };
    image.decoding = "async";
    image.src = src;

    if (image.complete && image.naturalWidth > 0) {
      resolve(image);
    }
  });
}

function createLoadedThemeAssets(assets: readonly NeonThemeImageAsset[]): NeonThemeAssets {
  const records = new Map<NeonThemeImageKey, NeonThemeImageAsset>();
  for (const asset of assets) {
    records.set(asset.key, asset);
  }

  return {
    getImage(key: NeonThemeImageKey): HTMLImageElement {
      const asset = records.get(key);
      if (!asset) {
        throw new Error(`Required visual asset is not loaded: ${key}`);
      }
      return asset.image;
    },
    snapshot(): readonly NeonThemeImageAsset[] {
      return [...records.values()];
    },
    dispose(): void {
      for (const asset of records.values()) {
        asset.image.onload = null;
        asset.image.onerror = null;
      }
      records.clear();
    }
  };
}

function getDefaultImageFactory(): (() => HTMLImageElement) | null {
  if (typeof Image === "undefined") {
    return null;
  }
  return () => new Image();
}

function isLoadedAssetResult(result: LoadedThemeAssetResult): result is Extract<LoadedThemeAssetResult, { readonly ok: true }> {
  return result.ok;
}

function isFailedAssetResult(result: LoadedThemeAssetResult): result is Extract<LoadedThemeAssetResult, { readonly ok: false }> {
  return !result.ok;
}
