/**
 * Defines responsive canvas layout contracts for iPhone and desktop rendering.
 */
import { BOARD_DIMENSIONS } from "../core/constants";

/** Platform layout mode derived from viewport dimensions. */
export type LayoutMode = "iphone-portrait" | "desktop" | "rotate-prompt" | "widen-prompt";

/** Optional app-provided device hint for ambiguous narrow viewports. */
export type LayoutDeviceClass = "iphone" | "desktop";

/** Safe-area insets measured in CSS pixels. */
export interface SafeAreaInsets {
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly left: number;
}

/** Generic rectangle in CSS pixels. */
export interface LayoutRect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** Viewport input for layout calculations. */
export interface ViewportMetrics {
  readonly widthPx: number;
  readonly heightPx: number;
  readonly devicePixelRatio: number;
  readonly safeArea: SafeAreaInsets;
  readonly deviceClass?: LayoutDeviceClass;
}

/** Computed board and sidebar layout. */
export interface GameLayout {
  readonly mode: LayoutMode;
  readonly canvasWidth: number;
  readonly canvasHeight: number;
  readonly backingScale: number;
  readonly safeContent: LayoutRect;
  readonly hud: LayoutRect;
  readonly board: LayoutRect;
  readonly sidebar: LayoutRect;
  readonly nextPreviewSlots: readonly LayoutRect[];
  readonly prompt: LayoutRect;
  readonly cellSizePx: number;
  readonly boardX: number;
  readonly boardY: number;
  readonly boardWidth: number;
  readonly boardHeight: number;
  readonly sidebarX: number;
  readonly sidebarWidth: number;
}

export const IPHONE_HUD_HEIGHT_PX = 36;
export const DESKTOP_HUD_HEIGHT_PX = 40;
export const DESKTOP_CELL_SIZE_PX = 32;
export const MIN_DESKTOP_PLAYABLE_WIDTH_PX = 420;
export const DESKTOP_MODE_WIDTH_PX = 600;

const IPHONE_MIN_WIDTH_PX = 375;
const IPHONE_MAX_WIDTH_PX = 430;
const MOBILE_LANDSCAPE_MAX_WIDTH_PX = 899;
const IPHONE_BOARD_WIDTH_RATIO = 0.7;
const IPHONE_MAIN_GAP_PX = 8;
const IPHONE_BOTTOM_GESTURE_RESERVE_PX = 24;
const DESKTOP_MAIN_GAP_PX = 8;
const DEFAULT_PROMPT_PADDING_PX = 24;
const MAX_BACKING_SCALE = 2;

/** Computes the game layout for the current viewport. */
export function computeGameLayout(metrics: ViewportMetrics): GameLayout {
  const canvasWidth = normalizeDimension(metrics.widthPx);
  const canvasHeight = normalizeDimension(metrics.heightPx);
  const backingScale = computeBackingScale(metrics.devicePixelRatio);
  const safeContent = computeSafeContent(canvasWidth, canvasHeight, metrics.safeArea);
  const mode = resolveLayoutMode(metrics, canvasWidth, canvasHeight);

  switch (mode) {
    case "iphone-portrait":
      return computeIphoneLayout(canvasWidth, canvasHeight, backingScale, safeContent);
    case "desktop":
      return computeDesktopLayout(canvasWidth, canvasHeight, backingScale, safeContent);
    case "rotate-prompt":
    case "widen-prompt":
      return computePromptLayout(mode, canvasWidth, canvasHeight, backingScale, safeContent);
  }
}

/** Returns the capped backing-store scale used for high-DPI Canvas rendering. */
export function computeBackingScale(devicePixelRatio: number): number {
  if (!Number.isFinite(devicePixelRatio) || devicePixelRatio <= 0) {
    return 1;
  }

  return Math.min(MAX_BACKING_SCALE, devicePixelRatio);
}

/** Returns the gameplay pause-button rectangle, or null when gameplay is not visible. */
export function getPauseButtonRect(layout: GameLayout): LayoutRect | null {
  if (layout.mode === "rotate-prompt" || layout.mode === "widen-prompt" || layout.hud.height <= 0) {
    return null;
  }

  const size = Math.max(24, Math.min(32, layout.hud.height - 4));
  return createRect(
    layout.hud.x + layout.hud.width - size,
    layout.hud.y + Math.floor((layout.hud.height - size) / 2),
    size,
    size
  );
}

function resolveLayoutMode(metrics: ViewportMetrics, canvasWidth: number, canvasHeight: number): LayoutMode {
  if (metrics.deviceClass === "iphone") {
    return canvasWidth > canvasHeight ? "rotate-prompt" : "iphone-portrait";
  }

  if (metrics.deviceClass === "desktop") {
    return canvasWidth < MIN_DESKTOP_PLAYABLE_WIDTH_PX ? "widen-prompt" : "desktop";
  }

  const hasSafeArea = hasNonZeroSafeArea(metrics.safeArea);
  if (canvasWidth > canvasHeight && (canvasWidth <= MOBILE_LANDSCAPE_MAX_WIDTH_PX || hasSafeArea)) {
    return "rotate-prompt";
  }

  const isIphonePortraitSize =
    canvasHeight >= canvasWidth && canvasWidth >= IPHONE_MIN_WIDTH_PX && canvasWidth <= IPHONE_MAX_WIDTH_PX;
  if (isIphonePortraitSize || (hasSafeArea && canvasHeight >= canvasWidth && canvasWidth < DESKTOP_MODE_WIDTH_PX)) {
    return "iphone-portrait";
  }

  return canvasWidth < MIN_DESKTOP_PLAYABLE_WIDTH_PX ? "widen-prompt" : "desktop";
}

function computeIphoneLayout(
  canvasWidth: number,
  canvasHeight: number,
  backingScale: number,
  safeContent: LayoutRect
): GameLayout {
  const maxCellByWidth = Math.floor((safeContent.width * IPHONE_BOARD_WIDTH_RATIO) / BOARD_DIMENSIONS.columns);
  const boardAreaHeight = Math.max(
    0,
    safeContent.height - IPHONE_HUD_HEIGHT_PX - IPHONE_MAIN_GAP_PX - IPHONE_BOTTOM_GESTURE_RESERVE_PX
  );
  const maxCellByHeight = Math.floor(boardAreaHeight / BOARD_DIMENSIONS.visibleRows);
  const cellSizePx = Math.max(12, Math.min(maxCellByWidth, maxCellByHeight));
  const boardWidth = cellSizePx * BOARD_DIMENSIONS.columns;
  const boardHeight = cellSizePx * BOARD_DIMENSIONS.visibleRows;
  const hud = createRect(safeContent.x, safeContent.y, safeContent.width, IPHONE_HUD_HEIGHT_PX);
  const board = createRect(safeContent.x, safeContent.y + IPHONE_HUD_HEIGHT_PX + IPHONE_MAIN_GAP_PX, boardWidth, boardHeight);
  const sidebarX = board.x + board.width + IPHONE_MAIN_GAP_PX;
  const sidebar = createRect(
    sidebarX,
    board.y,
    Math.max(0, safeContent.x + safeContent.width - sidebarX),
    board.height
  );

  return completeLayout({
    mode: "iphone-portrait",
    canvasWidth,
    canvasHeight,
    backingScale,
    safeContent,
    hud,
    board,
    sidebar,
    prompt: createPromptRect(safeContent),
    cellSizePx,
    nextPreviewSlots: computePreviewSlots(sidebar)
  });
}

function computeDesktopLayout(
  canvasWidth: number,
  canvasHeight: number,
  backingScale: number,
  safeContent: LayoutRect
): GameLayout {
  const compact = safeContent.width < DESKTOP_MODE_WIDTH_PX;
  const cellSizePx = DESKTOP_CELL_SIZE_PX;
  const boardWidth = cellSizePx * BOARD_DIMENSIONS.columns;
  const boardHeight = cellSizePx * BOARD_DIMENSIONS.visibleRows;
  const sidebarGap = compact ? 8 : 16;
  const sidebarWidth = compact ? Math.max(84, safeContent.width - boardWidth - sidebarGap) : 128;
  const totalWidth = boardWidth + sidebarGap + sidebarWidth;
  const totalHeight = DESKTOP_HUD_HEIGHT_PX + DESKTOP_MAIN_GAP_PX + boardHeight;
  const originX = safeContent.x + Math.max(0, Math.floor((safeContent.width - totalWidth) / 2));
  const originY = safeContent.y + Math.max(0, Math.floor((safeContent.height - totalHeight) / 2));
  const hud = createRect(originX, originY, totalWidth, DESKTOP_HUD_HEIGHT_PX);
  const board = createRect(originX, originY + DESKTOP_HUD_HEIGHT_PX + DESKTOP_MAIN_GAP_PX, boardWidth, boardHeight);
  const sidebar = createRect(board.x + board.width + sidebarGap, board.y, sidebarWidth, board.height);

  return completeLayout({
    mode: "desktop",
    canvasWidth,
    canvasHeight,
    backingScale,
    safeContent,
    hud,
    board,
    sidebar,
    prompt: createPromptRect(safeContent),
    cellSizePx,
    nextPreviewSlots: computePreviewSlots(sidebar)
  });
}

function computePromptLayout(
  mode: "rotate-prompt" | "widen-prompt",
  canvasWidth: number,
  canvasHeight: number,
  backingScale: number,
  safeContent: LayoutRect
): GameLayout {
  return completeLayout({
    mode,
    canvasWidth,
    canvasHeight,
    backingScale,
    safeContent,
    hud: createRect(safeContent.x, safeContent.y, safeContent.width, 0),
    board: createRect(safeContent.x, safeContent.y, 0, 0),
    sidebar: createRect(safeContent.x, safeContent.y, 0, 0),
    prompt: createPromptRect(safeContent),
    cellSizePx: 0,
    nextPreviewSlots: []
  });
}

function completeLayout(layout: Omit<GameLayout, "boardX" | "boardY" | "boardWidth" | "boardHeight" | "sidebarX" | "sidebarWidth">): GameLayout {
  return {
    ...layout,
    boardX: layout.board.x,
    boardY: layout.board.y,
    boardWidth: layout.board.width,
    boardHeight: layout.board.height,
    sidebarX: layout.sidebar.x,
    sidebarWidth: layout.sidebar.width
  };
}

function computeSafeContent(canvasWidth: number, canvasHeight: number, safeArea: SafeAreaInsets): LayoutRect {
  const left = normalizeInset(safeArea.left);
  const top = normalizeInset(safeArea.top);
  const right = normalizeInset(safeArea.right);
  const bottom = normalizeInset(safeArea.bottom);

  return createRect(
    left,
    top,
    Math.max(1, canvasWidth - left - right),
    Math.max(1, canvasHeight - top - bottom)
  );
}

function computePreviewSlots(sidebar: LayoutRect): readonly LayoutRect[] {
  if (sidebar.width <= 0 || sidebar.height <= 0) {
    return [];
  }

  const horizontalPadding = sidebar.width < 100 ? 8 : 12;
  const slotSize = Math.max(24, Math.min(72, Math.floor(sidebar.width - horizontalPadding * 2)));
  const slotGap = sidebar.width < 100 ? 8 : 12;
  const firstY = sidebar.y + 32;
  const slotX = sidebar.x + Math.floor((sidebar.width - slotSize) / 2);

  return [0, 1, 2].map((index) => {
    return createRect(slotX, firstY + index * (slotSize + slotGap), slotSize, slotSize);
  });
}

function createPromptRect(safeContent: LayoutRect): LayoutRect {
  return createRect(
    safeContent.x + DEFAULT_PROMPT_PADDING_PX,
    safeContent.y + DEFAULT_PROMPT_PADDING_PX,
    Math.max(1, safeContent.width - DEFAULT_PROMPT_PADDING_PX * 2),
    Math.max(1, safeContent.height - DEFAULT_PROMPT_PADDING_PX * 2)
  );
}

function createRect(x: number, y: number, width: number, height: number): LayoutRect {
  return {
    x,
    y,
    width,
    height
  };
}

function normalizeDimension(value: number): number {
  return Number.isFinite(value) ? Math.max(1, Math.floor(value)) : 1;
}

function normalizeInset(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
}

function hasNonZeroSafeArea(safeArea: SafeAreaInsets): boolean {
  return safeArea.top > 0 || safeArea.right > 0 || safeArea.bottom > 0 || safeArea.left > 0;
}
