/**
 * Defines rendering contracts for non-gameplay screens and overlays.
 */
import {
  computeScreenMenuLayout,
  getActiveScreen,
  getScreenTitle,
  isPromptScreen,
  type ScreenMenuLayout,
  type ScreenMenuItemRect,
  type ScreenStackSnapshot
} from "../app/screens";
import { CANVAS_COLORS } from "../render/palette";
import type { HighScoreEntry, HighScoreTable } from "../storage/high-scores";

/** Context available to screen rendering code. */
export interface ScreenRenderContext {
  readonly canvas: HTMLCanvasElement;
  readonly context: CanvasRenderingContext2D;
  readonly nowMs: number;
  readonly widthPx?: number;
  readonly heightPx?: number;
}

/** Draws the active screen stack over or instead of gameplay. */
export function renderScreenStack(screenStack: ScreenStackSnapshot, context: ScreenRenderContext): void {
  const activeScreen = getActiveScreen(screenStack);
  if (activeScreen === null || activeScreen === "gameplay") {
    return;
  }

  const size = getContextSize(context);
  const hasGameplayUnderlay = screenStack.screens.includes("gameplay");
  if (hasGameplayUnderlay || isPromptScreen(activeScreen)) {
    drawOverlay(context.context, size.width, size.height, isPromptScreen(activeScreen) ? 0.88 : 0.72);
  } else {
    fillBackground(context.context, size.width, size.height);
  }

  switch (activeScreen) {
    case "splash":
      drawSplash(context.context, size.width, size.height);
      break;
    case "main-menu":
    case "pause":
    case "high-score-entry":
    case "game-over":
    case "settings":
      drawMenu(context.context, computeScreenMenuLayout(activeScreen, size.width, size.height, screenStack));
      break;
    case "high-scores":
      drawHighScoresMenu(
        context.context,
        computeScreenMenuLayout(activeScreen, size.width, size.height, screenStack),
        screenStack.highScores
      );
      break;
    case "rotate-prompt":
    case "widen-prompt":
      drawPrompt(context.context, size.width, size.height, getScreenTitle(activeScreen));
      break;
  }
}

function getContextSize(context: ScreenRenderContext): { readonly width: number; readonly height: number } {
  const fallbackWidth = context.canvas.clientWidth || context.canvas.width;
  const fallbackHeight = context.canvas.clientHeight || context.canvas.height;

  return {
    width: context.widthPx ?? fallbackWidth,
    height: context.heightPx ?? fallbackHeight
  };
}

function fillBackground(context: CanvasRenderingContext2D, width: number, height: number): void {
  const gradient = context.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, "#05071a");
  gradient.addColorStop(0.7, "#071027");
  gradient.addColorStop(1, "#15091e");
  context.fillStyle = gradient;
  context.fillRect(0, 0, width, height);
  drawPixelFrame(context, width, height);
}

function drawOverlay(context: CanvasRenderingContext2D, width: number, height: number, alpha: number): void {
  context.save();
  context.fillStyle = `rgba(3, 4, 14, ${alpha})`;
  context.fillRect(0, 0, width, height);
  drawPixelFrame(context, width, height);
  context.restore();
}

function drawSplash(context: CanvasRenderingContext2D, width: number, height: number): void {
  context.save();
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillStyle = CANVAS_COLORS.hudText;
  context.shadowColor = "#a000f0";
  context.shadowBlur = 9;
  context.font = `${fitFontSize(context, "AGENTIC TETRIS", Math.min(30, width * 0.08), width - 48)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  context.fillText("AGENTIC TETRIS", width / 2, height / 2);
  context.restore();
}

function drawMenu(context: CanvasRenderingContext2D, layout: ScreenMenuLayout): void {
  context.save();
  drawMenuFrame(context, layout);

  for (const itemRect of layout.items) {
    drawMenuItem(context, itemRect.x, itemRect.y, itemRect.width, itemRect.height, itemRect.item.label, itemRect.item.muted);
  }

  context.restore();
}

function drawMenuFrame(context: CanvasRenderingContext2D, layout: ScreenMenuLayout): void {
  context.fillStyle = CANVAS_COLORS.panelFill;
  context.strokeStyle = "#3559c7";
  context.lineWidth = 1;
  context.fillRect(layout.panelX, layout.panelY, layout.panelWidth, layout.panelHeight);
  context.strokeRect(layout.panelX + 0.5, layout.panelY + 0.5, layout.panelWidth - 1, layout.panelHeight - 1);
  context.strokeStyle = "rgba(160, 0, 240, 0.52)";
  context.strokeRect(layout.panelX + 6.5, layout.panelY + 6.5, layout.panelWidth - 13, layout.panelHeight - 13);
  context.fillStyle = "rgba(240, 160, 0, 0.58)";
  context.fillRect(layout.panelX + 18, layout.panelY + 16, 36, 3);
  context.fillRect(layout.panelX + layout.panelWidth - 54, layout.panelY + 16, 36, 3);

  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillStyle = CANVAS_COLORS.hudText;
  context.shadowColor = "#00f0f0";
  context.shadowBlur = 6;
  context.font = `${fitFontSize(context, layout.title, 24, layout.panelWidth - 32)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  context.fillText(layout.title, layout.panelX + layout.panelWidth / 2, layout.panelY + 28);
  context.shadowBlur = 0;
}

function drawHighScoresMenu(
  context: CanvasRenderingContext2D,
  layout: ScreenMenuLayout,
  table: HighScoreTable | undefined
): void {
  context.save();
  drawMenuFrame(context, layout);

  for (const itemRect of layout.items) {
    if (itemRect.item.command === "back") {
      drawMenuItem(context, itemRect.x, itemRect.y, itemRect.width, itemRect.height, itemRect.item.label, false);
    }
  }

  drawHighScoreTable(context, layout, table?.entries ?? []);
  context.restore();
}

function drawHighScoreTable(
  context: CanvasRenderingContext2D,
  layout: ScreenMenuLayout,
  entries: readonly HighScoreEntry[]
): void {
  const tableRows = layout.items.filter((itemRect) => itemRect.item.command === null);
  if (tableRows.length === 0) {
    return;
  }

  const headerRow = tableRows[0];
  if (!headerRow) {
    return;
  }

  drawHighScoreHeader(context, headerRow);
  if (entries.length === 0) {
    const emptyRow = tableRows[1];
    if (emptyRow) {
      drawHighScoreEmptyRow(context, emptyRow);
    }
    return;
  }

  entries.slice(0, tableRows.length - 1).forEach((entry, index) => {
    const row = tableRows[index + 1];
    if (row) {
      drawHighScoreRow(context, row, entry, index + 1);
    }
  });
}

function drawHighScoreHeader(context: CanvasRenderingContext2D, row: ScreenMenuItemRect): void {
  drawHighScoreRowBackground(context, row, true);
  const columns = getHighScoreColumns(row);
  drawHighScoreCell(context, "RANK", columns.rankX, row.y, columns.rankWidth, row.height, "left", true);
  drawHighScoreCell(context, "PLAYER NAME", columns.nameX, row.y, columns.nameWidth, row.height, "left", true);
  drawHighScoreCell(context, "SCORE", columns.scoreX, row.y, columns.scoreWidth, row.height, "right", true);
  drawHighScoreCell(context, "DATE", columns.dateX, row.y, columns.dateWidth, row.height, "left", true);
  drawHighScoreSeparators(context, row, columns);
}

function drawHighScoreRow(
  context: CanvasRenderingContext2D,
  row: ScreenMenuItemRect,
  entry: HighScoreEntry,
  rank: number
): void {
  drawHighScoreRowBackground(context, row, false);
  const columns = getHighScoreColumns(row);
  drawHighScoreCell(context, String(rank).padStart(2, "0"), columns.rankX, row.y, columns.rankWidth, row.height, "left", false);
  drawHighScoreCell(context, entry.name, columns.nameX, row.y, columns.nameWidth, row.height, "left", false);
  drawHighScoreCell(context, formatInteger(entry.score), columns.scoreX, row.y, columns.scoreWidth, row.height, "right", false);
  drawHighScoreCell(context, formatHighScoreDate(entry.achievedAtIso), columns.dateX, row.y, columns.dateWidth, row.height, "left", false);
  drawHighScoreSeparators(context, row, columns);
}

function drawHighScoreEmptyRow(context: CanvasRenderingContext2D, row: ScreenMenuItemRect): void {
  drawHighScoreRowBackground(context, row, false);
  context.fillStyle = CANVAS_COLORS.hudMutedText;
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.font = `${fitFontSize(context, "NO SCORES", 13, row.width - 16)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  context.fillText("NO SCORES", row.x + row.width / 2, row.y + row.height / 2);
}

interface HighScoreColumnLayout {
  readonly rankX: number;
  readonly rankWidth: number;
  readonly nameX: number;
  readonly nameWidth: number;
  readonly scoreX: number;
  readonly scoreWidth: number;
  readonly dateX: number;
  readonly dateWidth: number;
  readonly separatorXs: readonly number[];
}

function getHighScoreColumns(row: ScreenMenuItemRect): HighScoreColumnLayout {
  const padding = 10;
  const separatorGap = 9;
  const innerWidth = row.width - padding * 2;
  const rankWidth = 34;
  const dateWidth = Math.min(70, Math.max(58, Math.floor(innerWidth * 0.26)));
  const scoreWidth = Math.min(58, Math.max(46, Math.floor(innerWidth * 0.2)));
  const nameWidth = Math.max(40, innerWidth - rankWidth - scoreWidth - dateWidth - separatorGap * 3);
  const rankX = row.x + padding;
  const nameX = rankX + rankWidth + separatorGap;
  const scoreX = nameX + nameWidth + separatorGap;
  const dateX = scoreX + scoreWidth + separatorGap;

  return {
    rankX,
    rankWidth,
    nameX,
    nameWidth,
    scoreX,
    scoreWidth,
    dateX,
    dateWidth,
    separatorXs: [
      rankX + rankWidth + Math.floor(separatorGap / 2),
      nameX + nameWidth + Math.floor(separatorGap / 2),
      scoreX + scoreWidth + Math.floor(separatorGap / 2)
    ]
  };
}

function drawHighScoreRowBackground(context: CanvasRenderingContext2D, row: ScreenMenuItemRect, header: boolean): void {
  context.fillStyle = header ? "rgba(6, 10, 28, 0.94)" : "rgba(4, 6, 18, 0.86)";
  context.strokeStyle = header ? "rgba(0, 240, 240, 0.42)" : "rgba(53, 89, 199, 0.7)";
  context.lineWidth = 1;
  context.fillRect(row.x, row.y, row.width, row.height);
  context.strokeRect(row.x + 0.5, row.y + 0.5, row.width - 1, row.height - 1);
}

function drawHighScoreSeparators(
  context: CanvasRenderingContext2D,
  row: ScreenMenuItemRect,
  columns: HighScoreColumnLayout
): void {
  context.save();
  context.strokeStyle = CANVAS_COLORS.panelStroke;
  context.lineWidth = 1;
  context.beginPath();
  for (const separatorX of columns.separatorXs) {
    const x = Math.floor(separatorX) + 0.5;
    context.moveTo(x, row.y + 8);
    context.lineTo(x, row.y + row.height - 8);
  }
  context.stroke();
  context.restore();
}

function drawHighScoreCell(
  context: CanvasRenderingContext2D,
  label: string,
  x: number,
  y: number,
  width: number,
  height: number,
  align: CanvasTextAlign,
  header: boolean
): void {
  context.fillStyle = header ? CANVAS_COLORS.hudText : CANVAS_COLORS.hudMutedText;
  context.textAlign = align;
  context.textBaseline = "middle";
  context.font = `${fitFontSize(context, label, header ? 11 : 12, width)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  const textX = align === "right" ? x + width : x;
  context.fillText(label, textX, y + height / 2);
}

function drawMenuItem(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  label: string,
  muted: boolean
): void {
  context.strokeStyle = "rgba(0, 240, 240, 0.52)";
  context.fillStyle = "rgba(4, 6, 18, 0.86)";
  context.fillRect(x, y, width, height);
  context.strokeRect(x + 0.5, y + 0.5, width - 1, height - 1);
  context.fillStyle = muted ? CANVAS_COLORS.hudMutedText : CANVAS_COLORS.hudText;
  context.shadowColor = muted ? "transparent" : "#a000f0";
  context.shadowBlur = muted ? 0 : 5;
  context.font = `${fitFontSize(context, label, 15, width - 16)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  context.fillText(label, x + width / 2, y + height / 2);
  context.shadowBlur = 0;
}

function drawPrompt(context: CanvasRenderingContext2D, width: number, height: number, label: string): void {
  context.save();
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillStyle = CANVAS_COLORS.hudText;
  context.shadowColor = "#00f0f0";
  context.shadowBlur = 8;
  context.font = `${fitFontSize(context, label, 22, width - 48)}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
  context.fillText(label, width / 2, height / 2);
  context.restore();
}

function drawPixelFrame(context: CanvasRenderingContext2D, width: number, height: number): void {
  const borderWidth = Math.min(34, Math.max(18, Math.floor(width * 0.08)));
  context.save();
  context.fillStyle = "rgba(23, 9, 27, 0.78)";
  context.fillRect(0, 0, borderWidth, height);
  context.fillRect(width - borderWidth, 0, borderWidth, height);
  context.fillStyle = "rgba(129, 48, 22, 0.84)";
  context.fillRect(4, 0, 4, height);
  context.fillRect(width - 8, 0, 4, height);
  context.fillStyle = "rgba(189, 90, 27, 0.8)";
  for (let y = 12; y < height; y += 56) {
    context.fillRect(12, y, Math.max(6, borderWidth - 24), 7);
    context.fillRect(width - borderWidth + 12, y, Math.max(6, borderWidth - 24), 7);
  }
  context.restore();
}

function formatInteger(value: number): string {
  return Math.max(0, Math.trunc(value)).toLocaleString("en-US");
}

function formatHighScoreDate(achievedAtIso: string): string {
  const timestamp = Date.parse(achievedAtIso);
  if (Number.isNaN(timestamp)) {
    return "----------";
  }
  return new Date(timestamp).toISOString().slice(0, 10);
}

function fitFontSize(
  context: CanvasRenderingContext2D,
  text: string,
  preferredPx: number,
  maxWidthPx: number
): number {
  let size = Math.max(10, Math.floor(preferredPx));
  while (size > 10) {
    context.font = `${size}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
    if (context.measureText(text).width <= maxWidthPx) {
      return size;
    }
    size -= 1;
  }
  return size;
}
