/**
 * Owns Canvas 2D drawing calls and consumes render snapshots from browser orchestration.
 */
import { getBoardCell, type BoardCell, type BoardPoint } from "../core/board";
import { BOARD_DIMENSIONS } from "../core/constants";
import type { SerializableGameState } from "../core/game-state";
import {
  getActivePieceCells,
  getPieceDefinition,
  type ActivePiece,
  type TetrominoKind
} from "../core/pieces";
import { renderScreenStack } from "../screens/screen-renderer";
import { computeBackingScale, getPauseButtonRect, type GameLayout, type LayoutRect } from "./layout";
import { CANVAS_COLORS, getTetrominoColor } from "./palette";
import type { RenderFrame, RenderVisualEvents } from "./render-state";
import type { NeonThemeAssets, NeonThemeImageKey } from "./theme-assets";

/** Construction options for the Canvas renderer. */
export interface CanvasRendererOptions {
  readonly canvas: HTMLCanvasElement;
  readonly themeAssets: NeonThemeAssets;
}

/** Canvas renderer contract used by the app shell. */
export interface CanvasRenderer {
  render(frame: RenderFrame): void;
  dispose(): void;
}

/** Creates a Canvas 2D renderer. */
export function createCanvasRenderer(options: CanvasRendererOptions): CanvasRenderer {
  const context = options.canvas.getContext("2d");
  if (!context) {
    throw new Error("Canvas 2D context is unavailable");
  }
  const themeAssets = options.themeAssets;
  const state: CanvasSizeState = {
    cssWidth: options.canvas.clientWidth || options.canvas.width,
    cssHeight: options.canvas.clientHeight || options.canvas.height,
    backingScale: computeRuntimeBackingScale(),
    stageBackgroundStyleKey: null,
    lastClearMode: null,
    lastGameplayClearKey: null,
    effects: createInitialEffectState()
  };
  configureBackingStore(options.canvas, context, state.cssWidth, state.cssHeight, state.backingScale);

  return {
    render(frame: RenderFrame): void {
      const size = frame.layout
        ? configureBackingStore(options.canvas, context, frame.layout.canvasWidth, frame.layout.canvasHeight, frame.layout.backingScale)
        : syncBackingStoreToDisplay(options.canvas, context, state);
      clearFrame(context, frame, size, state);
      syncStageBackgroundStyle(options.canvas, frame.layout ?? null, themeAssets, state);

      if (frame.layout?.mode === "rotate-prompt") {
        drawPrompt(context, frame.layout, "ROTATE TO PORTRAIT");
      } else if (frame.layout?.mode === "widen-prompt") {
        drawPrompt(context, frame.layout, "WIDEN WINDOW");
      } else if (frame.layout && frame.game) {
        updateEffectState(state.effects, frame.game, frame.nowMs);
        drawGameplay(context, frame.game, frame.layout, themeAssets, state.effects, frame.visualEvents ?? null, frame.nowMs);
      }

      if (frame.screenStack) {
        renderScreenStack(frame.screenStack, {
          canvas: options.canvas,
          context,
          nowMs: frame.nowMs,
          widthPx: size.cssWidth,
          heightPx: size.cssHeight
        });
      }
    },
    dispose(): void {
      syncStageBackgroundStyle(options.canvas, null, themeAssets, state);
      themeAssets.dispose();
      return;
    }
  };
}

interface CanvasSizeState {
  cssWidth: number;
  cssHeight: number;
  backingScale: number;
  stageBackgroundStyleKey: string | null;
  lastClearMode: CanvasClearMode | null;
  lastGameplayClearKey: string | null;
  readonly effects: RenderEffectState;
}

type CanvasClearMode = "full" | "gameplay";

interface ConfiguredCanvasSize {
  readonly cssWidth: number;
  readonly cssHeight: number;
  readonly backingScale: number;
  readonly backingWidth: number;
  readonly backingHeight: number;
}

function syncBackingStoreToDisplay(
  canvas: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
  state: CanvasSizeState
): ConfiguredCanvasSize {
  const cssWidth = canvas.clientWidth || state.cssWidth || canvas.width;
  const cssHeight = canvas.clientHeight || state.cssHeight || canvas.height;
  const backingScale = computeRuntimeBackingScale();
  const size = configureBackingStore(canvas, context, cssWidth, cssHeight, backingScale);
  state.cssWidth = size.cssWidth;
  state.cssHeight = size.cssHeight;
  state.backingScale = size.backingScale;
  return size;
}

function configureBackingStore(
  canvas: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
  widthPx: number,
  heightPx: number,
  backingScale: number
): ConfiguredCanvasSize {
  const cssWidth = normalizeCanvasDimension(widthPx);
  const cssHeight = normalizeCanvasDimension(heightPx);
  const normalizedScale = computeBackingScale(backingScale);
  const backingWidth = Math.max(1, Math.floor(cssWidth * normalizedScale));
  const backingHeight = Math.max(1, Math.floor(cssHeight * normalizedScale));

  if (canvas.width !== backingWidth) {
    canvas.width = backingWidth;
  }
  if (canvas.height !== backingHeight) {
    canvas.height = backingHeight;
  }
  canvas.style.width = `${cssWidth}px`;
  canvas.style.height = `${cssHeight}px`;
  context.setTransform(normalizedScale, 0, 0, normalizedScale, 0, 0);
  context.imageSmoothingEnabled = false;

  return {
    cssWidth,
    cssHeight,
    backingScale: normalizedScale,
    backingWidth,
    backingHeight
  };
}

function clearCanvas(context: CanvasRenderingContext2D, width: number, height: number): void {
  context.clearRect(0, 0, width, height);
}

function clearFrame(
  context: CanvasRenderingContext2D,
  frame: RenderFrame,
  size: ConfiguredCanvasSize,
  state: CanvasSizeState
): void {
  // Menus/prompts/overlays can dirty the whole canvas, so only stable active
  // gameplay frames use the smaller clear region.
  const clearMode = getCanvasClearMode(frame);
  const gameplayClearKey = clearMode === "gameplay" && frame.layout ? getGameplayClearKey(frame.layout) : null;
  const canClearGameplayOnly =
    clearMode === "gameplay" &&
    state.lastClearMode === "gameplay" &&
    state.lastGameplayClearKey === gameplayClearKey &&
    frame.layout !== null;

  if (canClearGameplayOnly && frame.layout) {
    clearGameplayArea(context, frame.layout, size.cssWidth, size.cssHeight);
  } else {
    clearCanvas(context, size.cssWidth, size.cssHeight);
  }

  state.lastClearMode = clearMode;
  state.lastGameplayClearKey = gameplayClearKey;
}

function getCanvasClearMode(frame: RenderFrame): CanvasClearMode {
  if (!frame.layout || !frame.game || frame.layout.mode === "rotate-prompt" || frame.layout.mode === "widen-prompt") {
    return "full";
  }

  return getFrameActiveScreen(frame) === "gameplay" ? "gameplay" : "full";
}

function getFrameActiveScreen(frame: RenderFrame): string | null {
  const screens = frame.screenStack?.screens;
  return screens && screens.length > 0 ? screens[screens.length - 1] ?? null : null;
}

function getGameplayClearKey(layout: GameLayout): string {
  // Partial clear is valid only while these bounds stay fixed; layout or mode
  // changes force a full clear first.
  return [
    layout.mode,
    layout.canvasWidth,
    layout.canvasHeight,
    layout.hud.x,
    layout.hud.y,
    layout.hud.width,
    layout.hud.height,
    layout.board.x,
    layout.board.y,
    layout.board.width,
    layout.board.height,
    layout.sidebar.x,
    layout.sidebar.y,
    layout.sidebar.width,
    layout.sidebar.height
  ].join(":");
}

function clearGameplayArea(context: CanvasRenderingContext2D, layout: GameLayout, canvasWidth: number, canvasHeight: number): void {
  // Include padding for shadows, score pops, and hard-drop trails that draw just
  // outside the panel bounds.
  const margin = 24;
  const left = Math.max(0, Math.floor(Math.min(layout.hud.x, layout.board.x, layout.sidebar.x) - margin));
  const top = Math.max(0, Math.floor(Math.min(layout.hud.y, layout.board.y, layout.sidebar.y) - margin));
  const right = Math.min(
    canvasWidth,
    Math.ceil(Math.max(layout.hud.x + layout.hud.width, layout.board.x + layout.board.width, layout.sidebar.x + layout.sidebar.width) + margin)
  );
  const bottom = Math.min(
    canvasHeight,
    Math.ceil(Math.max(layout.hud.y + layout.hud.height, layout.board.y + layout.board.height, layout.sidebar.y + layout.sidebar.height) + margin)
  );

  context.clearRect(left, top, Math.max(1, right - left), Math.max(1, bottom - top));
}

const STAGE_BACKGROUND_COLOR = "#050714";
const STAGE_VIGNETTE_BACKGROUND =
  "radial-gradient(circle at 50% 52%, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0) 32%, rgba(0, 0, 0, 0.38) 100%)";

function syncStageBackgroundStyle(
  canvas: HTMLCanvasElement,
  layout: GameLayout | null,
  themeAssets: NeonThemeAssets,
  state: CanvasSizeState
): void {
  if (!layout) {
    clearStageBackgroundStyle(canvas, state);
    return;
  }

  const imageKey: NeonThemeImageKey = layout.mode === "desktop" ? "desktopBackground" : "portraitBackground";
  const image = themeAssets.getImage(imageKey);
  const imageUrl = image.currentSrc || image.src;
  const styleKey = `${imageKey}:${imageUrl}`;

  if (state.stageBackgroundStyleKey === styleKey) {
    return;
  }

  state.stageBackgroundStyleKey = styleKey;
  canvas.style.backgroundColor = STAGE_BACKGROUND_COLOR;
  canvas.style.backgroundImage = `${STAGE_VIGNETTE_BACKGROUND}, ${toCssUrl(imageUrl)}`;
  canvas.style.backgroundPosition = "center center, center center";
  canvas.style.backgroundRepeat = "no-repeat, no-repeat";
  canvas.style.backgroundSize = "100% 100%, cover";
}

function clearStageBackgroundStyle(canvas: HTMLCanvasElement, state: CanvasSizeState): void {
  if (state.stageBackgroundStyleKey === null) {
    return;
  }

  state.stageBackgroundStyleKey = null;
  canvas.style.backgroundColor = "";
  canvas.style.backgroundImage = "";
  canvas.style.backgroundPosition = "";
  canvas.style.backgroundRepeat = "";
  canvas.style.backgroundSize = "";
}

function toCssUrl(url: string): string {
  return `url(${JSON.stringify(url)})`;
}

interface RenderEffectState {
  lastLockKey: string | null;
  lockStartedAtMs: number;
  scorePopStartedAtMs: number;
  scorePopPoints: number;
  gameOverStartedAtMs: number | null;
  lastPhase: string | null;
  lastScore: number;
}

function createInitialEffectState(): RenderEffectState {
  return {
    lastLockKey: null,
    lockStartedAtMs: 0,
    scorePopStartedAtMs: 0,
    scorePopPoints: 0,
    gameOverStartedAtMs: null,
    lastPhase: null,
    lastScore: 0
  };
}

function updateEffectState(effects: RenderEffectState, game: SerializableGameState, nowMs: number): void {
  const lockKey = game.lastLock
    ? `${game.score.score}:${game.lastLock.piece}:${game.lastLock.awardedPoints}:${game.lastLock.clearedRows.join(".")}`
    : null;

  if (lockKey && lockKey !== effects.lastLockKey) {
    effects.lastLockKey = lockKey;
    effects.lockStartedAtMs = nowMs;
    if (game.lastLock && game.lastLock.awardedPoints > 0) {
      effects.scorePopStartedAtMs = nowMs;
      effects.scorePopPoints = game.lastLock.awardedPoints;
    }
  }

  if (game.score.score < effects.lastScore) {
    effects.scorePopPoints = 0;
  }
  effects.lastScore = game.score.score;

  if (game.phase === "game-over" && effects.lastPhase !== "game-over") {
    effects.gameOverStartedAtMs = nowMs;
  }
  if (game.phase !== "game-over") {
    effects.gameOverStartedAtMs = null;
  }
  effects.lastPhase = game.phase;
}

function drawGameplay(
  context: CanvasRenderingContext2D,
  game: SerializableGameState,
  layout: GameLayout,
  themeAssets: NeonThemeAssets,
  effects: RenderEffectState,
  visualEvents: RenderVisualEvents | null,
  nowMs: number
): void {
  drawHud(context, game, layout);
  drawBoardBackground(context, layout);
  drawGrid(context, layout);
  drawLockedCells(context, game, layout, themeAssets);
  drawPiece(context, game.ghostPiece, layout, themeAssets, 0.25);
  drawHardDropTrail(context, layout, visualEvents, nowMs);
  drawPiece(context, game.activePiece, layout, themeAssets, 1);
  drawLineClearEffect(context, game, layout, themeAssets, effects, nowMs);
  drawNextPreview(context, game, layout, themeAssets);
  drawScorePop(context, layout, effects, nowMs);
  drawGameOverFade(context, game, layout, effects, nowMs);
}

function drawHud(context: CanvasRenderingContext2D, game: SerializableGameState, layout: GameLayout): void {
  const fontSize = layout.mode === "desktop" ? 16 : 13;
  const y = layout.hud.y + layout.hud.height / 2;
  const third = layout.hud.width / 3;
  const pauseButton = getPauseButtonRect(layout);
  const rightEdge = pauseButton ? pauseButton.x - 8 : layout.hud.x + layout.hud.width;
  context.save();
  drawNeonPanel(context, layout.hud, "hudPanel");
  context.textBaseline = "middle";
  context.fillStyle = CANVAS_COLORS.hudText;
  context.shadowColor = "#00f0f0";
  context.shadowBlur = 5;
  drawFittedText(context, `SCORE ${formatInteger(game.score.score)}`, layout.hud.x, y, third * 1.35, fontSize, "left");
  drawFittedText(context, `LVL ${game.score.level}`, layout.hud.x + third * 1.45, y, third * 0.65, fontSize, "center");
  drawFittedText(context, `LNS ${game.score.lines}`, rightEdge, y, third, fontSize, "right");
  if (pauseButton) {
    drawPauseButton(context, pauseButton);
  }
  context.restore();
}

function drawPauseButton(context: CanvasRenderingContext2D, rect: LayoutRect): void {
  context.strokeStyle = "#00f0f0";
  context.fillStyle = "rgba(5, 7, 19, 0.88)";
  context.lineWidth = 1;
  context.fillRect(rect.x, rect.y, rect.width, rect.height);
  context.strokeRect(crisp(rect.x), crisp(rect.y), Math.max(1, rect.width - 1), Math.max(1, rect.height - 1));
  context.fillStyle = CANVAS_COLORS.hudText;
  const barWidth = Math.max(3, Math.floor(rect.width * 0.12));
  const barHeight = Math.max(12, Math.floor(rect.height * 0.48));
  const gap = Math.max(4, Math.floor(rect.width * 0.16));
  const leftX = Math.floor(rect.x + (rect.width - barWidth * 2 - gap) / 2);
  const barY = Math.floor(rect.y + (rect.height - barHeight) / 2);
  context.fillRect(leftX, barY, barWidth, barHeight);
  context.fillRect(leftX + barWidth + gap, barY, barWidth, barHeight);
}

function drawBoardBackground(context: CanvasRenderingContext2D, layout: GameLayout): void {
  context.fillStyle = "rgba(4, 6, 18, 0.84)";
  context.fillRect(layout.board.x, layout.board.y, layout.board.width, layout.board.height);
  context.strokeStyle = "rgba(0, 240, 240, 0.38)";
  context.lineWidth = 2;
  context.strokeRect(crisp(layout.board.x), crisp(layout.board.y), Math.max(1, layout.board.width - 1), Math.max(1, layout.board.height - 1));
}

function drawGrid(context: CanvasRenderingContext2D, layout: GameLayout): void {
  context.save();
  context.strokeStyle = "rgba(48, 78, 174, 0.38)";
  context.lineWidth = 1;
  context.beginPath();

  for (let col = 0; col <= BOARD_DIMENSIONS.columns; col += 1) {
    const x = crisp(layout.board.x + col * layout.cellSizePx);
    context.moveTo(x, layout.board.y);
    context.lineTo(x, layout.board.y + layout.board.height);
  }

  for (let row = 0; row <= BOARD_DIMENSIONS.visibleRows; row += 1) {
    const y = crisp(layout.board.y + row * layout.cellSizePx);
    context.moveTo(layout.board.x, y);
    context.lineTo(layout.board.x + layout.board.width, y);
  }

  context.stroke();
  context.restore();
}

function drawLockedCells(
  context: CanvasRenderingContext2D,
  game: SerializableGameState,
  layout: GameLayout,
  themeAssets: NeonThemeAssets
): void {
  for (let visibleRow = 0; visibleRow < game.board.visibleRows; visibleRow += 1) {
    const logicalRow = visibleRow + game.board.bufferRows;
    for (let col = 0; col < game.board.columns; col += 1) {
      const cell = getBoardCell(game.board, { col, row: logicalRow });
      drawBoardCell(context, cell, { col, row: visibleRow }, layout, themeAssets);
    }
  }
}

function drawBoardCell(
  context: CanvasRenderingContext2D,
  cell: BoardCell,
  visiblePoint: BoardPoint,
  layout: GameLayout,
  themeAssets: NeonThemeAssets
): void {
  if (!cell.occupied) {
    return;
  }

  drawBlock(context, cell.piece, visiblePoint.col, visiblePoint.row, layout, themeAssets);
}

function drawPiece(
  context: CanvasRenderingContext2D,
  piece: ActivePiece | null,
  layout: GameLayout,
  themeAssets: NeonThemeAssets,
  alpha: number
): void {
  if (piece === null) {
    return;
  }

  context.save();
  context.globalAlpha = alpha;
  for (const point of getActivePieceCells(piece)) {
    const visibleRow = point.row - BOARD_DIMENSIONS.bufferRows;
    if (visibleRow < 0 || visibleRow >= BOARD_DIMENSIONS.visibleRows) {
      continue;
    }
    drawBlock(context, piece.kind, point.col, visibleRow, layout, themeAssets);
  }
  context.restore();
}

function drawBlock(
  context: CanvasRenderingContext2D,
  kind: TetrominoKind,
  col: number,
  row: number,
  layout: GameLayout,
  themeAssets: NeonThemeAssets
): void {
  const x = layout.board.x + col * layout.cellSizePx;
  const y = layout.board.y + row * layout.cellSizePx;
  context.drawImage(themeAssets.getImage("neonCells"), getSpriteIndex(kind) * 64, 0, 64, 64, x, y, layout.cellSizePx, layout.cellSizePx);
}

function drawNextPreview(
  context: CanvasRenderingContext2D,
  game: SerializableGameState,
  layout: GameLayout,
  themeAssets: NeonThemeAssets
): void {
  context.save();
  drawNeonPanel(context, layout.sidebar, "hudPanel");
  context.fillStyle = CANVAS_COLORS.hudText;
  context.textAlign = "center";
  context.textBaseline = "middle";
  const titleY = layout.sidebar.y + 13;
  drawFittedText(context, "NEXT", layout.sidebar.x + layout.sidebar.width / 2, titleY, layout.sidebar.width - 8, 13, "center");

  const previewCount = Math.min(game.settings.nextPieceCount, game.nextQueue.length, layout.nextPreviewSlots.length);
  for (let index = 0; index < previewCount; index += 1) {
    const kind = game.nextQueue[index];
    const slot = layout.nextPreviewSlots[index];
    if (!kind || !slot) {
      continue;
    }

    drawPreviewSlot(context, slot, themeAssets);
    drawPreviewPiece(context, kind, slot, themeAssets);
  }
  context.restore();
}

function drawPreviewSlot(context: CanvasRenderingContext2D, slot: LayoutRect, themeAssets: NeonThemeAssets): void {
  context.drawImage(themeAssets.getImage("previewSlot"), slot.x, slot.y, slot.width, slot.height);
}

function drawPreviewPiece(context: CanvasRenderingContext2D, kind: TetrominoKind, slot: LayoutRect, themeAssets: NeonThemeAssets): void {
  const definition = getPieceDefinition(kind);
  const cells = definition.cellsByRotation["0"];
  const minCol = Math.min(...cells.map((cell) => cell.col));
  const maxCol = Math.max(...cells.map((cell) => cell.col));
  const minRow = Math.min(...cells.map((cell) => cell.row));
  const maxRow = Math.max(...cells.map((cell) => cell.row));
  const shapeColumns = maxCol - minCol + 1;
  const shapeRows = maxRow - minRow + 1;
  const previewCellSize = Math.max(8, Math.floor(Math.min(slot.width / (shapeColumns + 1), slot.height / (shapeRows + 1))));
  const originX = slot.x + Math.floor((slot.width - shapeColumns * previewCellSize) / 2) - minCol * previewCellSize;
  const originY = slot.y + Math.floor((slot.height - shapeRows * previewCellSize) / 2) - minRow * previewCellSize;
  const sheet = themeAssets.getImage("neonCells");

  for (const cell of cells) {
    const x = originX + cell.col * previewCellSize;
    const y = originY + cell.row * previewCellSize;
    context.drawImage(sheet, getSpriteIndex(kind) * 64, 0, 64, 64, x, y, previewCellSize, previewCellSize);
  }
}

function drawLineClearEffect(
  context: CanvasRenderingContext2D,
  game: SerializableGameState,
  layout: GameLayout,
  themeAssets: NeonThemeAssets,
  effects: RenderEffectState,
  nowMs: number
): void {
  if (!game.lastLock || game.lastLock.clearedLines === 0) {
    return;
  }
  const age = nowMs - effects.lockStartedAtMs;
  if (age < 0 || age > 320) {
    return;
  }

  const progress = Math.min(1, age / 320);
  const alpha = 1 - progress;
  const assetKey: NeonThemeImageKey = game.lastLock.clearedLines === 4 ? "tetrisBurst" : "lineClear";
  const asset = themeAssets.getImage(assetKey);
  context.save();
  context.globalAlpha = Math.max(0, alpha);
  if (game.lastLock.clearedLines === 4) {
    const visibleRows = game.lastLock.clearedRows
      .map((logicalRow) => logicalRow - BOARD_DIMENSIONS.bufferRows)
      .filter((visibleRow) => visibleRow >= 0 && visibleRow < BOARD_DIMENSIONS.visibleRows);
    if (visibleRows.length > 0) {
      const firstRow = Math.min(...visibleRows);
      const lastRow = Math.max(...visibleRows);
      const y = layout.board.y + firstRow * layout.cellSizePx;
      const height = (lastRow - firstRow + 1) * layout.cellSizePx;
      context.drawImage(asset, layout.board.x, y, layout.board.width, height);
    }
    context.restore();
    return;
  }
  for (const logicalRow of game.lastLock.clearedRows) {
    const visibleRow = logicalRow - BOARD_DIMENSIONS.bufferRows;
    if (visibleRow < 0 || visibleRow >= BOARD_DIMENSIONS.visibleRows) {
      continue;
    }
    const y = layout.board.y + visibleRow * layout.cellSizePx;
    context.drawImage(asset, layout.board.x, y, layout.board.width, layout.cellSizePx);
  }
  context.restore();
}

function drawHardDropTrail(
  context: CanvasRenderingContext2D,
  layout: GameLayout,
  visualEvents: RenderVisualEvents | null,
  nowMs: number
): void {
  const hardDrop = visualEvents?.hardDrop;
  if (!hardDrop) {
    return;
  }
  const age = nowMs - hardDrop.occurredAtMs;
  if (age < 0 || age > 150) {
    return;
  }
  context.save();
  context.globalAlpha = 0.18 * (1 - age / 150);
  context.fillStyle = getTetrominoColor(hardDrop.piece.kind);
  for (const point of getActivePieceCells(hardDrop.piece)) {
    const visibleRow = point.row - BOARD_DIMENSIONS.bufferRows;
    if (visibleRow < 0) {
      continue;
    }
    const x = layout.board.x + point.col * layout.cellSizePx + layout.cellSizePx * 0.38;
    const y = layout.board.y + Math.max(0, visibleRow) * layout.cellSizePx;
    context.fillRect(x, y, Math.max(2, layout.cellSizePx * 0.24), layout.board.y + layout.board.height - y);
  }
  context.restore();
}

function drawScorePop(context: CanvasRenderingContext2D, layout: GameLayout, effects: RenderEffectState, nowMs: number): void {
  if (effects.scorePopPoints <= 0) {
    return;
  }
  const age = nowMs - effects.scorePopStartedAtMs;
  if (age < 0 || age > 700) {
    return;
  }
  const progress = age / 700;
  context.save();
  context.globalAlpha = 1 - progress;
  context.fillStyle = "#f0f000";
  context.shadowColor = "#f0a000";
  context.shadowBlur = 8;
  drawFittedText(
    context,
    `+${formatInteger(effects.scorePopPoints)}`,
    layout.hud.x + layout.hud.width * 0.5,
    layout.hud.y + layout.hud.height + 16 - progress * 18,
    layout.hud.width * 0.5,
    14,
    "center"
  );
  context.restore();
}

function drawGameOverFade(
  context: CanvasRenderingContext2D,
  game: SerializableGameState,
  layout: GameLayout,
  effects: RenderEffectState,
  nowMs: number
): void {
  if (game.phase !== "game-over" || effects.gameOverStartedAtMs === null) {
    return;
  }
  const age = nowMs - effects.gameOverStartedAtMs;
  const alpha = Math.min(0.28, Math.max(0, age / 800) * 0.28);
  context.fillStyle = `rgba(160, 0, 240, ${alpha})`;
  context.fillRect(layout.board.x, layout.board.y, layout.board.width, layout.board.height);
}

function drawNeonPanel(context: CanvasRenderingContext2D, rect: LayoutRect, assetKey: NeonThemeImageKey): void {
  const accent = assetKey === "hudPanel" ? "rgba(0, 240, 240, 0.42)" : "rgba(160, 0, 240, 0.42)";
  context.save();
  context.fillStyle = "rgba(4, 6, 18, 0.72)";
  context.fillRect(rect.x, rect.y, rect.width, rect.height);
  context.strokeStyle = accent;
  context.lineWidth = 1;
  context.strokeRect(crisp(rect.x), crisp(rect.y), Math.max(1, rect.width - 1), Math.max(1, rect.height - 1));
  context.restore();
}

function getSpriteIndex(kind: TetrominoKind): number {
  switch (kind) {
    case "I":
      return 0;
    case "O":
      return 1;
    case "T":
      return 2;
    case "S":
      return 3;
    case "Z":
      return 4;
    case "J":
      return 5;
    case "L":
      return 6;
  }
}

function drawPrompt(context: CanvasRenderingContext2D, layout: GameLayout, label: string): void {
  context.save();
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillStyle = CANVAS_COLORS.hudText;
  drawFittedText(
    context,
    label,
    layout.prompt.x + layout.prompt.width / 2,
    layout.prompt.y + layout.prompt.height / 2,
    layout.prompt.width,
    22,
    "center"
  );
  context.restore();
}

function drawFittedText(
  context: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  preferredSize: number,
  align: CanvasTextAlign
): void {
  let size = Math.max(10, Math.floor(preferredSize));
  context.textAlign = align;
  context.font = font(size);

  while (size > 10 && context.measureText(text).width > maxWidth) {
    size -= 1;
    context.font = font(size);
  }

  context.fillText(text, x, y);
}

function font(size: number): string {
  return `${size}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace`;
}

function formatInteger(value: number): string {
  return Math.trunc(value).toLocaleString("en-US");
}

function crisp(value: number): number {
  return Math.floor(value) + 0.5;
}

function normalizeCanvasDimension(value: number): number {
  return Number.isFinite(value) ? Math.max(1, Math.floor(value)) : 1;
}

function computeRuntimeBackingScale(): number {
  return computeBackingScale(typeof window === "undefined" ? 1 : window.devicePixelRatio);
}
