/**
 * Defines settings persisted through the browser storage adapter.
 */
import type { StorageAdapter } from "./storage-adapter";

/** User settings locked by the UX spec. */
export interface UserSettings {
  readonly ghostEnabled: boolean;
  readonly nextPieceCount: 1 | 3;
  readonly soundEnabled: boolean;
}

export const DEFAULT_SETTINGS: UserSettings = {
  ghostEnabled: true,
  nextPieceCount: 1,
  soundEnabled: true
};

export const SETTINGS_STORAGE_KEY = "agentic-tetris:settings:v1";

/** Parses persisted settings data. */
export function parseSettings(raw: string | null): UserSettings {
  if (raw === null) {
    return DEFAULT_SETTINGS;
  }

  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isRecord(parsed)) {
      return DEFAULT_SETTINGS;
    }

    return {
      ghostEnabled: typeof parsed.ghostEnabled === "boolean" ? parsed.ghostEnabled : DEFAULT_SETTINGS.ghostEnabled,
      nextPieceCount: parsed.nextPieceCount === 3 ? 3 : DEFAULT_SETTINGS.nextPieceCount,
      soundEnabled: typeof parsed.soundEnabled === "boolean" ? parsed.soundEnabled : DEFAULT_SETTINGS.soundEnabled
    };
  } catch {
    return DEFAULT_SETTINGS;
  }
}

/** Serializes settings for persistence. */
export function serializeSettings(settings: UserSettings): string {
  return JSON.stringify(normalizeSettings(settings));
}

/** Loads settings from storage with corrupted data fallback. */
export function loadSettings(adapter: StorageAdapter, key = SETTINGS_STORAGE_KEY): UserSettings {
  try {
    return parseSettings(adapter.getString(key));
  } catch {
    return DEFAULT_SETTINGS;
  }
}

/** Saves settings to storage, ignoring unavailable-storage failures. */
export function saveSettings(adapter: StorageAdapter, settings: UserSettings, key = SETTINGS_STORAGE_KEY): void {
  try {
    adapter.setString(key, serializeSettings(settings));
  } catch {
    return;
  }
}

/** Returns a settings object constrained to UX-spec-supported values. */
export function normalizeSettings(settings: UserSettings): UserSettings {
  return {
    ghostEnabled: settings.ghostEnabled === true,
    nextPieceCount: settings.nextPieceCount === 3 ? 3 : 1,
    soundEnabled: settings.soundEnabled === true
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
