/**
 * Defines persistent high-score storage contracts.
 */
import type { StorageAdapter } from "./storage-adapter";

/** One locally persisted high-score entry. */
export interface HighScoreEntry {
  readonly name: string;
  readonly score: number;
  readonly lines: number;
  readonly level: number;
  readonly achievedAtIso: string;
}

/** Final game-over score before the player name is collected. */
export interface HighScoreCandidate {
  readonly score: number;
  readonly lines: number;
  readonly level: number;
  readonly achievedAtIso: string;
}

/** High-score table persisted across sessions. */
export interface HighScoreTable {
  readonly entries: readonly HighScoreEntry[];
}

export const HIGH_SCORES_STORAGE_KEY = "agentic-tetris:high-scores:v1";
export const HIGH_SCORE_LIMIT = 10;
export const HIGH_SCORE_DEFAULT_NAME = "UNSUNG HERO";
export const HIGH_SCORE_NAME_MAX_LENGTH = 10;

/** Returns an empty high-score table. */
export function createEmptyHighScoreTable(): HighScoreTable {
  return { entries: [] };
}

/** Inserts a score into a top-10 high-score table. */
export function addHighScore(table: HighScoreTable, entry: HighScoreEntry): HighScoreTable {
  const normalizedEntry = normalizeHighScoreEntry(entry);
  if (normalizedEntry.score <= 0) {
    return normalizeHighScoreTable(table);
  }

  const entries = [...normalizeHighScoreTable(table).entries, normalizedEntry];
  entries.sort(compareHighScoreEntries);
  return {
    entries: entries.slice(0, HIGH_SCORE_LIMIT)
  };
}

/** Returns true when the candidate belongs in the local top-10 table. */
export function isQualifyingHighScore(table: HighScoreTable, candidate: HighScoreCandidate): boolean {
  const normalizedCandidate = normalizeHighScoreCandidate(candidate);
  if (normalizedCandidate.score <= 0) {
    return false;
  }

  const entries = normalizeHighScoreTable(table).entries;
  if (entries.length < HIGH_SCORE_LIMIT) {
    return true;
  }

  const lowestEntry = entries[entries.length - 1];
  return lowestEntry ? compareHighScoreEntries(candidateToEntry(normalizedCandidate), lowestEntry) < 0 : true;
}

/** Normalizes a player-entered high-score display name. */
export function normalizeHighScoreName(name: string): string {
  const strippedName = Array.from(name)
    .filter((character) => !isControlCharacter(character))
    .join("")
    .replace(/\s+/g, " ")
    .trim();
  if (strippedName.length === 0) {
    return HIGH_SCORE_DEFAULT_NAME;
  }
  if (strippedName === HIGH_SCORE_DEFAULT_NAME) {
    return HIGH_SCORE_DEFAULT_NAME;
  }

  const clippedName = Array.from(strippedName).slice(0, HIGH_SCORE_NAME_MAX_LENGTH).join("").trim();
  return clippedName.length > 0 ? clippedName : HIGH_SCORE_DEFAULT_NAME;
}

/** Parses persisted high scores with corrupted data fallback. */
export function parseHighScoreTable(raw: string | null): HighScoreTable {
  if (raw === null) {
    return createEmptyHighScoreTable();
  }

  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isRecord(parsed) || !Array.isArray(parsed.entries)) {
      return createEmptyHighScoreTable();
    }

    return normalizeHighScoreTable({
      entries: parsed.entries.map((entry) => {
        return isRecord(entry) ? entryToHighScore(entry) : null;
      }).filter((entry): entry is HighScoreEntry => entry !== null)
    });
  } catch {
    return createEmptyHighScoreTable();
  }
}

/** Serializes a high-score table for persistence. */
export function serializeHighScoreTable(table: HighScoreTable): string {
  return JSON.stringify(normalizeHighScoreTable(table));
}

/** Loads high scores from storage with corrupted data fallback. */
export function loadHighScores(adapter: StorageAdapter, key = HIGH_SCORES_STORAGE_KEY): HighScoreTable {
  try {
    return parseHighScoreTable(adapter.getString(key));
  } catch {
    return createEmptyHighScoreTable();
  }
}

/** Saves high scores to storage, ignoring unavailable-storage failures. */
export function saveHighScores(adapter: StorageAdapter, table: HighScoreTable, key = HIGH_SCORES_STORAGE_KEY): void {
  try {
    adapter.setString(key, serializeHighScoreTable(table));
  } catch {
    return;
  }
}

/** Returns a table constrained to the local top-10 contract. */
export function normalizeHighScoreTable(table: HighScoreTable): HighScoreTable {
  const entries = table.entries.map(normalizeHighScoreEntry).filter((entry) => entry.score > 0);
  entries.sort(compareHighScoreEntries);
  return {
    entries: entries.slice(0, HIGH_SCORE_LIMIT)
  };
}

/** Compares entries in leaderboard order. */
export function compareHighScoreEntries(left: HighScoreEntry, right: HighScoreEntry): number {
  const leftCandidate = normalizeHighScoreCandidate(left);
  const rightCandidate = normalizeHighScoreCandidate(right);
  if (rightCandidate.score !== leftCandidate.score) {
    return rightCandidate.score - leftCandidate.score;
  }
  if (rightCandidate.lines !== leftCandidate.lines) {
    return rightCandidate.lines - leftCandidate.lines;
  }
  if (rightCandidate.level !== leftCandidate.level) {
    return rightCandidate.level - leftCandidate.level;
  }
  return leftCandidate.achievedAtIso.localeCompare(rightCandidate.achievedAtIso);
}

function normalizeHighScoreEntry(entry: HighScoreEntry): HighScoreEntry {
  return {
    ...normalizeHighScoreCandidate(entry),
    name: normalizeHighScoreName(entry.name)
  };
}

function normalizeHighScoreCandidate(entry: HighScoreCandidate): HighScoreCandidate {
  return {
    score: normalizeNonNegativeInteger(entry.score),
    lines: normalizeNonNegativeInteger(entry.lines),
    level: Math.max(1, normalizeNonNegativeInteger(entry.level)),
    achievedAtIso: isValidIsoDate(entry.achievedAtIso) ? entry.achievedAtIso : new Date(0).toISOString()
  };
}

function entryToHighScore(entry: Record<string, unknown>): HighScoreEntry | null {
  if (
    typeof entry.score !== "number" ||
    typeof entry.lines !== "number" ||
    typeof entry.level !== "number" ||
    typeof entry.achievedAtIso !== "string"
  ) {
    return null;
  }

  return normalizeHighScoreEntry({
    name: typeof entry.name === "string" ? entry.name : HIGH_SCORE_DEFAULT_NAME,
    score: entry.score,
    lines: entry.lines,
    level: entry.level,
    achievedAtIso: entry.achievedAtIso
  });
}

function candidateToEntry(candidate: HighScoreCandidate): HighScoreEntry {
  return {
    ...candidate,
    name: HIGH_SCORE_DEFAULT_NAME
  };
}

function normalizeNonNegativeInteger(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : 0;
}

function isValidIsoDate(value: string): boolean {
  return !Number.isNaN(Date.parse(value));
}

function isControlCharacter(character: string): boolean {
  const codePoint = character.codePointAt(0);
  return codePoint === undefined || codePoint < 32 || codePoint === 127;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
