/**
 * Defines tetromino identifiers, active piece state, and piece definition contracts.
 */
import type { BoardPoint } from "./board";

/** The seven tetrominoes included by the gameplay spec. */
export type TetrominoKind = "I" | "O" | "T" | "S" | "Z" | "J" | "L";

/** SRS rotation state labels. */
export type RotationState = "0" | "R" | "2" | "L";

/** A matrix cell occupied by a piece definition. */
export interface PieceCell {
  readonly col: number;
  readonly row: number;
}

/** Static piece definition for one tetromino. */
export interface PieceDefinition {
  readonly kind: TetrominoKind;
  readonly color: string;
  readonly boundingBoxSize: number;
  readonly spawn: BoardPoint;
  readonly cellsByRotation: Readonly<Record<RotationState, readonly PieceCell[]>>;
}

/** Active falling piece state. */
export interface ActivePiece {
  readonly kind: TetrominoKind;
  readonly origin: BoardPoint;
  readonly rotation: RotationState;
}

