/** Returns the static definition for a tetromino. */
export function getPieceDefinition(kind: TetrominoKind): PieceDefinition {
  return PIECE_DEFINITIONS[kind];
}

/** Returns occupied board points for an active piece. */
export function getActivePieceCells(piece: ActivePiece): readonly BoardPoint[] {
  const definition = getPieceDefinition(piece.kind);
  return definition.cellsByRotation[piece.rotation].map((cell) => {
    return {
      col: piece.origin.col + cell.col,
      row: piece.origin.row + cell.row
    };
  });
}

/** Creates a new active piece at its gameplay-spec spawn position. */
export function createActivePiece(kind: TetrominoKind): ActivePiece {
  const definition = getPieceDefinition(kind);
  return {
    kind,
    origin: definition.spawn,
    rotation: "0"
  };
}
