/**
 * Owns board representation contracts for the pure Tetris logic layer.
 */
import { BOARD_DIMENSIONS } from "./constants";
import { getActivePieceCells, type ActivePiece, type TetrominoKind } from "./pieces";

/** Integer board coordinate with origin at the top-left logical cell. */
export interface BoardPoint {
  readonly col: number;
  readonly row: number;
}

/** A locked board cell or an empty board cell. */
export type BoardCell =
  | { readonly occupied: false }
  | { readonly occupied: true; readonly piece: TetrominoKind };

/** Immutable board representation including buffer rows. */
export interface Board {
  readonly columns: number;
  readonly rows: number;
  readonly visibleRows: number;
  readonly bufferRows: number;
  readonly cells: readonly BoardCell[];
}

/** Result of clearing all currently full rows. */
export interface LineClearResult {
  readonly board: Board;
  readonly clearedRows: readonly number[];
}

export const EMPTY_CELL: BoardCell = { occupied: false };

/** Creates an empty board with the gameplay-spec dimensions. */
export function createEmptyBoard(): Board {
  return {
    columns: BOARD_DIMENSIONS.columns,
    rows: BOARD_DIMENSIONS.totalRows,
    visibleRows: BOARD_DIMENSIONS.visibleRows,
    bufferRows: BOARD_DIMENSIONS.bufferRows,
    cells: Array.from({ length: BOARD_DIMENSIONS.columns * BOARD_DIMENSIONS.totalRows }, () => EMPTY_CELL)
  };
}

/** Returns the cell at a board coordinate. */
export function getBoardCell(board: Board, point: BoardPoint): BoardCell {
  assertInsideBoard(board, point);
  return board.cells[getBoardIndex(board, point)] ?? EMPTY_CELL;
}

/** Returns whether a coordinate is inside the logical board. */
export function isInsideBoard(board: Board, point: BoardPoint): boolean {
  return point.col >= 0 && point.col < board.columns && point.row >= 0 && point.row < board.rows;
}

/** Returns the flat-array index for a coordinate. */
export function getBoardIndex(board: Board, point: BoardPoint): number {
  assertInsideBoard(board, point);
  return point.row * board.columns + point.col;
}

/** Returns a new board with one cell replaced. */
export function setBoardCell(board: Board, point: BoardPoint, cell: BoardCell): Board {
  const index = getBoardIndex(board, point);
  const cells = board.cells.slice();
  cells[index] = cell;
  return { ...board, cells };
}

/** Returns true when a coordinate is inside the board and occupied. */
export function isCellOccupied(board: Board, point: BoardPoint): boolean {
  return isInsideBoard(board, point) ? getBoardCell(board, point).occupied : false;
}

/** Returns true if the active piece can occupy its current cells on the board. */
export function canPlacePiece(board: Board, piece: ActivePiece): boolean {
  return getActivePieceCells(piece).every((point) => {
    return isInsideBoard(board, point) && !getBoardCell(board, point).occupied;
  });
}

/** Returns a new board with an active piece locked into occupied cells. */
export function lockPieceToBoard(board: Board, piece: ActivePiece): Board {
  return getActivePieceCells(piece).reduce<Board>((nextBoard, point) => {
    if (!isInsideBoard(nextBoard, point)) {
      throw new RangeError(`Cannot lock piece cell outside board at col ${point.col}, row ${point.row}`);
    }

    return setBoardCell(nextBoard, point, { occupied: true, piece: piece.kind });
  }, board);
}

/** Returns true when every cell in a row is occupied. */
export function isRowFull(board: Board, row: number): boolean {
  assertRowInsideBoard(board, row);
  for (let col = 0; col < board.columns; col += 1) {
    if (!getBoardCell(board, { col, row }).occupied) {
      return false;
    }
  }

  return true;
}

/** Returns every full row index in ascending order. */
export function findFullRows(board: Board): readonly number[] {
  const fullRows: number[] = [];
  for (let row = 0; row < board.rows; row += 1) {
    if (isRowFull(board, row)) {
      fullRows.push(row);
    }
  }

  return fullRows;
}

/** Clears all full rows, preserving board height by adding empty rows at the top. */
export function clearFullLines(board: Board): LineClearResult {
  const clearedRows = findFullRows(board);
  if (clearedRows.length === 0) {
    return { board, clearedRows };
  }

  const cleared = new Set<number>(clearedRows);
  const remainingRows: readonly BoardCell[][] = Array.from({ length: board.rows }, (_, row) => {
    return board.cells.slice(row * board.columns, row * board.columns + board.columns);
  }).filter((_, row) => !cleared.has(row));

  const emptyRows = Array.from({ length: clearedRows.length }, () => {
    return Array.from({ length: board.columns }, () => EMPTY_CELL);
  });
  const rows = [...emptyRows, ...remainingRows];
  const cells = rows.flat();

  return {
    board: { ...board, cells },
    clearedRows
  };
}

function assertInsideBoard(board: Board, point: BoardPoint): void {
  if (!isInsideBoard(board, point)) {
    throw new RangeError(`Board point out of bounds: col ${point.col}, row ${point.row}`);
  }
}

function assertRowInsideBoard(board: Board, row: number): void {
  if (row < 0 || row >= board.rows) {
    throw new RangeError(`Board row out of bounds: ${row}`);
  }
}
