/**
 * Owns gravity timing contracts for wall-clock-driven piece drops.
 */
import { GRAVITY_SCHEDULE } from "./constants";

/** Mutable gravity timer state owned by the core engine. */
export interface GravityState {
  readonly level: number;
  readonly elapsedSinceDropMs: number;
}

/** Result of advancing gravity by elapsed wall-clock time. */
export interface GravityAdvance {
  readonly state: GravityState;
  readonly rowsToDrop: number;
}

/** Returns the drop interval for a level. */
export function getDropIntervalMs(level: number): number {
  const normalizedLevel = Math.max(1, Math.trunc(level));
  const entry = GRAVITY_SCHEDULE.find((candidate) => {
    return (
      normalizedLevel >= candidate.minLevel &&
      (candidate.maxLevel === null || normalizedLevel <= candidate.maxLevel)
    );
  });

  if (entry === undefined) {
    const finalEntry = GRAVITY_SCHEDULE[GRAVITY_SCHEDULE.length - 1];
    if (finalEntry === undefined) {
      throw new Error("Gravity schedule is empty");
    }
    return finalEntry.dropIntervalMs;
  }

  return entry.dropIntervalMs;
}

/** Advances gravity and reports how many rows the active piece should drop. */
export function advanceGravity(state: GravityState, elapsedMs: number): GravityAdvance {
  const interval = getDropIntervalMs(state.level);
  const totalElapsed = state.elapsedSinceDropMs + Math.max(0, elapsedMs);
  const rowsToDrop = Math.floor(totalElapsed / interval);
  const elapsedSinceDropMs = totalElapsed % interval;

  return {
    state: {
      level: state.level,
      elapsedSinceDropMs
    },
    rowsToDrop
  };
}
