/**
 * Browser entry point that wires the static HTML canvas to the application shell.
 */
import { bootstrapApp } from "./app/app";

/** Starts the browser application once the DOM entry point is available. */
export async function main(): Promise<void> {
  const canvas = document.querySelector<HTMLCanvasElement>("#game-canvas");
  if (!canvas) {
    throw new Error("Missing #game-canvas element");
  }

  await bootstrapApp({ canvas });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => {
    void main();
  }, { once: true });
} else {
  void main();
}
