/**
 * Defines browser lifecycle hooks that can pause or resume gameplay orchestration.
 */

/** Lifecycle events that the browser shell can emit to the game orchestrator. */
export type BrowserLifecycleEvent =
  | "visibility-hidden"
  | "visibility-visible"
  | "window-blur"
  | "window-focus"
  | "orientation-restricted"
  | "orientation-restored";

/** Callback for lifecycle events that affect game state. */
export type BrowserLifecycleHandler = (event: BrowserLifecycleEvent) => void;

/** Disposable browser lifecycle subscription. */
export interface BrowserLifecycleSubscription {
  dispose(): void;
}

/** Browser globals used by lifecycle wiring; injectable for tests. */
export interface BrowserLifecycleTargets {
  readonly window?: Window;
  readonly document?: Document;
  readonly orientationQuery?: MediaQueryList;
}

/** Attaches lifecycle event listeners for pause/resume orchestration. */
export function attachBrowserLifecycle(
  handler: BrowserLifecycleHandler,
  targets: BrowserLifecycleTargets = {}
): BrowserLifecycleSubscription {
  const targetWindow = targets.window ?? (typeof window === "undefined" ? null : window);
  const targetDocument = targets.document ?? (typeof document === "undefined" ? null : document);
  const orientationQuery =
    targets.orientationQuery ??
    (targetWindow ? targetWindow.matchMedia("(orientation: landscape) and (max-width: 899px)") : null);

  const disposers: Array<() => void> = [];

  if (targetDocument) {
    const handleVisibilityChange = (): void => {
      handler(targetDocument.visibilityState === "hidden" ? "visibility-hidden" : "visibility-visible");
    };
    targetDocument.addEventListener("visibilitychange", handleVisibilityChange);
    disposers.push(() => targetDocument.removeEventListener("visibilitychange", handleVisibilityChange));
  }

  if (targetWindow) {
    const handleBlur = (): void => handler("window-blur");
    const handleFocus = (): void => handler("window-focus");
    targetWindow.addEventListener("blur", handleBlur);
    targetWindow.addEventListener("focus", handleFocus);
    disposers.push(() => targetWindow.removeEventListener("blur", handleBlur));
    disposers.push(() => targetWindow.removeEventListener("focus", handleFocus));
  }

  if (orientationQuery) {
    const handleOrientationChange = (): void => {
      handler(orientationQuery.matches ? "orientation-restricted" : "orientation-restored");
    };
    orientationQuery.addEventListener("change", handleOrientationChange);
    disposers.push(() => orientationQuery.removeEventListener("change", handleOrientationChange));
    handleOrientationChange();
  }

  return {
    dispose(): void {
      for (const dispose of disposers.splice(0)) {
        dispose();
      }
    }
  };
}
