/**
 * Exposes locked gameplay constants from the gameplay and UX specs.
 */
import type { TetrominoKind } from "./pieces";

/** Board dimensions from the gameplay spec. */
export interface BoardDimensions {
  readonly columns: number;
  readonly visibleRows: number;
  readonly bufferRows: number;
  readonly totalRows: number;
}

/** Gesture and repeat timings from the UX spec. */
export interface TimingConstants {
  readonly lockDelayMs: number;
  readonly lockDelayResetCap: number;
  readonly dasMs: number;
  readonly arrMs: number;
}

/** Gravity schedule entry for one or more levels. */
export interface GravityScheduleEntry {
  readonly minLevel: number;
  readonly maxLevel: number | null;
  readonly dropIntervalMs: number;
}

export const BOARD_DIMENSIONS: BoardDimensions = {
  columns: 10,
  visibleRows: 20,
  bufferRows: 2,
  totalRows: 22
};

export const TIMING_CONSTANTS: TimingConstants = {
  lockDelayMs: 500,
  lockDelayResetCap: 15,
  dasMs: 167,
  arrMs: 33
};

