export const TETROMINO_KINDS: readonly TetrominoKind[] = ["I", "O", "T", "S", "Z", "J", "L"];

/** Returns the locked board dimensions from the gameplay spec. */
export function getBoardDimensions(): BoardDimensions {
  return BOARD_DIMENSIONS;
}

/** Returns timing constants used by movement and lock-delay systems. */
export function getTimingConstants(): TimingConstants {
  return TIMING_CONSTANTS;
}

/** Returns the locked gravity schedule from the gameplay spec. */
export function getGravitySchedule(): readonly GravityScheduleEntry[] {
  return GRAVITY_SCHEDULE;
}
