/**
 * Defines scoring, combo, back-to-back, and level progression contracts.
 */

/** Score and progression state displayed to the player. */
export interface ScoreState {
  readonly score: number;
  readonly level: number;
  readonly lines: number;
  readonly combo: number;
  readonly backToBackTetris: boolean;
}

/** Line clear event produced by the core board logic. */
export interface LineClearEvent {
  readonly clearedLines: 0 | 1 | 2 | 3 | 4;
  readonly softDropCells: number;
  readonly hardDropCells: number;
}

/** Result of applying one scoring event. */
export interface ScoreResult {
  readonly state: ScoreState;
  readonly awardedPoints: number;
}

/** Creates the starting score state. */
export function createInitialScoreState(level = 1): ScoreState {
  const normalizedLevel = Math.max(1, Math.trunc(level));
  return {
    score: 0,
    level: normalizedLevel,
    lines: (normalizedLevel - 1) * 10,
    combo: -1,
    backToBackTetris: false
  };
}

/** Applies line-clear and drop scoring to a score state. */
export function applyScoringEvent(state: ScoreState, event: LineClearEvent): ScoreResult {
  const dropPoints = event.softDropCells + event.hardDropCells * 2;

  if (event.clearedLines === 0) {
    const nextState: ScoreState = {
      ...state,
      score: state.score + dropPoints,
      combo: -1
    };

    return {
      state: nextState,
      awardedPoints: dropPoints
    };
  }

  const baseLinePoints = getLineClearPoints(event.clearedLines, state.level, state.backToBackTetris);
  const nextCombo = state.combo + 1;
  const comboPoints = 50 * nextCombo * state.level;
  const awardedPoints = baseLinePoints + comboPoints + dropPoints;
  const nextLines = state.lines + event.clearedLines;
  const nextLevel = Math.floor(nextLines / 10) + 1;
  const nextState: ScoreState = {
    score: state.score + awardedPoints,
    level: nextLevel,
    lines: nextLines,
    combo: nextCombo,
    backToBackTetris: event.clearedLines === 4
  };

  return {
    state: nextState,
    awardedPoints
  };
}

/** Returns line-clear points before combo and drop bonuses. */
export function getLineClearPoints(clearedLines: 0 | 1 | 2 | 3 | 4, level: number, backToBackTetris: boolean): number {
  switch (clearedLines) {
    case 0:
      return 0;
    case 1:
      return 100 * level;
    case 2:
      return 300 * level;
    case 3:
      return 500 * level;
    case 4:
      return Math.floor(800 * level * (backToBackTetris ? 1.5 : 1));
  }
}
