/**
 * Wraps browser storage so persistence is isolated from pure game logic.
 */

/** Minimal key-value storage contract used by settings and high scores. */
export interface StorageAdapter {
  getString(key: string): string | null;
  setString(key: string, value: string): void;
  removeString(key: string): void;
}

/** Creates a storage adapter backed by browser localStorage. */
export function createLocalStorageAdapter(storage: Storage): StorageAdapter {
  return {
    getString(key: string): string | null {
      return storage.getItem(key);
    },
    setString(key: string, value: string): void {
      storage.setItem(key, value);
    },
    removeString(key: string): void {
      storage.removeItem(key);
    }
  };
}

/** Creates an in-memory adapter useful for tests and storage-unavailable fallbacks. */
export function createMemoryStorageAdapter(initialValues: Readonly<Record<string, string>> = {}): StorageAdapter {
  const values = new Map<string, string>(Object.entries(initialValues));

  return {
    getString(key: string): string | null {
      return values.get(key) ?? null;
    },
    setString(key: string, value: string): void {
      values.set(key, value);
    },
    removeString(key: string): void {
      values.delete(key);
    }
  };
}
