/**
 * Owns DOM touch listener attachment and event cancellation for iPhone gameplay.
 */
import type { PlayerAction } from "../core/actions";
import type { GestureRecognizer, TouchSample } from "./gesture-recognizer";

/** Subscription returned by touch input attachment. */
export interface TouchInputSubscription {
  reset(timeMs?: number): void;
  dispose(): void;
}

/** Runtime data the recognizer needs from the current rendered layout. */
export interface TouchInputOptions {
  readonly getHorizontalCellSizePt?: () => number;
}

/** Converts a DOM touch list to normalized touch samples. */
export function samplesFromTouchList(touches: TouchList, timeMs: number): readonly TouchSample[] {
  return Array.from(touches, (touch) => ({
    id: touch.identifier,
    xPt: touch.clientX,
    yPt: touch.clientY,
    timeMs
  }));
}

/** Attaches touch listeners that emit player actions through a gesture recognizer. */
export function attachTouchInput(
  target: HTMLElement,
  recognizer: GestureRecognizer,
  dispatch: (action: PlayerAction) => void,
  options: TouchInputOptions = {}
): TouchInputSubscription {
  const previousTouchAction = target.style.touchAction;
  target.style.touchAction = "none";

  const handleStart = (event: TouchEvent): void => {
    event.preventDefault();
    syncHorizontalCellSize(event.timeStamp);
    dispatchAll(recognizer.start(samplesFromTouchList(event.touches, event.timeStamp)), dispatch);
  };

  const handleMove = (event: TouchEvent): void => {
    event.preventDefault();
    syncHorizontalCellSize(event.timeStamp);
    dispatchAll(recognizer.move(samplesFromTouchList(event.touches, event.timeStamp)), dispatch);
  };

  const handleEnd = (event: TouchEvent): void => {
    event.preventDefault();
    syncHorizontalCellSize(event.timeStamp);
    dispatchAll(recognizer.end(samplesFromTouchList(event.changedTouches, event.timeStamp)), dispatch);
  };

  const handleCancel = (event: TouchEvent): void => {
    event.preventDefault();
    dispatchAll(recognizer.cancel(event.timeStamp), dispatch);
  };

  const reset = (timeMs?: number): void => {
    dispatchAll(recognizer.cancel(timeMs), dispatch);
  };

  const syncHorizontalCellSize = (timeMs: number): void => {
    if (!options.getHorizontalCellSizePt) {
      return;
    }
    dispatchAll(recognizer.setHorizontalCellSizePt(options.getHorizontalCellSizePt(), timeMs), dispatch);
  };

  const listenerOptions: AddEventListenerOptions = { passive: false };
  target.addEventListener("touchstart", handleStart, listenerOptions);
  target.addEventListener("touchmove", handleMove, listenerOptions);
  target.addEventListener("touchend", handleEnd, listenerOptions);
  target.addEventListener("touchcancel", handleCancel, listenerOptions);

  return {
    reset,
    dispose(): void {
      target.removeEventListener("touchstart", handleStart);
      target.removeEventListener("touchmove", handleMove);
      target.removeEventListener("touchend", handleEnd);
      target.removeEventListener("touchcancel", handleCancel);
      reset();
      target.style.touchAction = previousTouchAction;
    }
  };
}

function dispatchAll(
  actions: readonly PlayerAction[],
  dispatch: (action: PlayerAction) => void
): void {
  for (const action of actions) {
    dispatch(action);
  }
}
