/**
 * Defines the deterministic 7-bag randomizer contract for the pure logic layer.
 */
import { TETROMINO_KINDS } from "./constants";
import type { TetrominoKind } from "./pieces";

/** Serializable randomizer state. */
export interface RandomizerState {
  readonly seed: string;
  readonly bag: readonly TetrominoKind[];
  readonly queue: readonly TetrominoKind[];
  readonly draws: number;
}

/** Randomizer capable of drawing tetrominoes and exposing upcoming queue state. */
export interface PieceRandomizer {
  draw(): readonly [TetrominoKind, RandomizerState];
  peek(count: 1 | 3): readonly TetrominoKind[];
  snapshot(): RandomizerState;
}

/** Creates a deterministic 7-bag randomizer. */
export function createSevenBagRandomizer(seed: string): PieceRandomizer {
  const random = createSeededRandom(seed);
  let bag: TetrominoKind[] = [];
  let queue: TetrominoKind[] = [];
  let draws = 0;

  const fillQueue = (count: number): void => {
    while (queue.length < count) {
      if (bag.length === 0) {
        bag = shuffleBag(random);
      }

      const next = bag.shift();
      if (next === undefined) {
        throw new Error("7-bag randomizer failed to draw a piece");
      }
      queue.push(next);
    }
  };

  const snapshot = (): RandomizerState => {
    return {
      seed,
      bag: [...bag],
      queue: [...queue],
      draws
    };
  };

  fillQueue(3);

  return {
    draw(): readonly [TetrominoKind, RandomizerState] {
      fillQueue(1);
      const next = queue.shift();
      if (next === undefined) {
        throw new Error("7-bag randomizer queue was unexpectedly empty");
      }

      draws += 1;
      fillQueue(3);
      return [next, snapshot()] as const;
    },
    peek(count: 1 | 3): readonly TetrominoKind[] {
      fillQueue(count);
      return queue.slice(0, count);
    },
    snapshot
  };
}

function shuffleBag(random: () => number): TetrominoKind[] {
  const bag = [...TETROMINO_KINDS];
  for (let index = bag.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(random() * (index + 1));
    const current = bag[index];
    const swap = bag[swapIndex];
    if (current === undefined || swap === undefined) {
      throw new Error("7-bag shuffle index out of range");
    }

    bag[index] = swap;
    bag[swapIndex] = current;
  }

  return bag;
}

function createSeededRandom(seed: string): () => number {
  let state = hashSeed(seed);
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function hashSeed(seed: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < seed.length; index += 1) {
    const code = seed.charCodeAt(index);
    hash ^= code;
    hash = Math.imul(hash, 0x01000193);
  }

  return hash >>> 0;
}
