/**
 * Composes browser-facing systems without owning game rules or rendering details.
 */
import { createAudioEngine, type SoundCue } from "../audio/audio-engine";
import type { PlayerAction } from "../core/actions";
import type { Board } from "../core/board";
import {
  getState,
  initGame,
  injectInput,
  tick as tickEngine,
  type GameEngine
} from "../core/engine";
import type { SerializableGameState } from "../core/game-state";
import { createGestureRecognizer } from "../input/gesture-recognizer";
import { attachKeyboardInput, type KeyboardInputSubscription } from "../input/keyboard";
import { attachTouchInput, type TouchInputSubscription } from "../input/touch-controller";
import { registerServiceWorker } from "../pwa/registration";
import { createCanvasRenderer, type CanvasRenderer } from "../render/canvas-renderer";
import type { RenderVisualEvents } from "../render/render-state";
import {
  loadNeonThemeAssets,
  NeonThemeAssetLoadError,
  type NeonThemeAssets
} from "../render/theme-assets";
import {
  computeGameLayout,
  getPauseButtonRect,
  type GameLayout,
  type LayoutDeviceClass,
  type SafeAreaInsets
} from "../render/layout";
import {
  addHighScore,
  isQualifyingHighScore,
  loadHighScores,
  saveHighScores,
  type HighScoreCandidate,
  type HighScoreTable
} from "../storage/high-scores";
import {
  loadSettings,
  saveSettings,
  type UserSettings
} from "../storage/settings";
import {
  createLocalStorageAdapter,
  createMemoryStorageAdapter,
  type StorageAdapter
} from "../storage/storage-adapter";
import {
  attachBrowserLifecycle,
  type BrowserLifecycleEvent,
  type BrowserLifecycleSubscription
} from "./lifecycle";
import {
  getActiveScreen,
  getInitialScreenStack,
  hitTestScreenCommand,
  type ScreenCommand,
  type ScreenId,
  type ScreenStackSnapshot
} from "./screens";
import { createScreenStateMachine } from "./state-machine";

type PromptScreen = Extract<ScreenId, "rotate-prompt" | "widen-prompt">;

/** Options required to bootstrap the browser application. */
export interface AppBootOptions {
  readonly canvas: HTMLCanvasElement;
  readonly registerServiceWorker?: boolean;
  readonly storageAdapter?: StorageAdapter;
  readonly seedFactory?: () => string;
  readonly nowIso?: () => string;
  readonly themeAssetsLoader?: () => Promise<NeonThemeAssets>;
}

/** Runtime handle returned by the application shell. */
export interface AppRuntime {
  readonly canvas: HTMLCanvasElement;
  start(): Promise<void>;
  resetInput(): void;
  snapshot(): GameOrchestratorSnapshot;
  stop(): void;
}

/** Effects requested by app orchestration after a transition. */
export interface GameOrchestratorEffects {
  readonly resetInput: boolean;
}

/** Options for the pure app/game orchestrator. */
export interface GameOrchestratorOptions {
  readonly storageAdapter?: StorageAdapter;
  readonly initialScreenStack?: ScreenStackSnapshot;
  readonly seedFactory?: () => string;
  readonly nowIso?: () => string;
  readonly initialBoard?: Board;
}

/** Snapshot exposed by the pure app/game orchestrator. */
export interface GameOrchestratorSnapshot {
  readonly game: SerializableGameState | null;
  readonly screenStack: ScreenStackSnapshot;
  readonly settings: UserSettings;
  readonly highScores: HighScoreTable;
  readonly pendingHighScore: HighScoreCandidate | null;
  readonly activeScreen: ScreenId;
  readonly prompt: PromptScreen | null;
}

/** Pure app/game orchestrator contract used by browser code and integration tests. */
export interface GameOrchestrator {
  snapshot(): GameOrchestratorSnapshot;
  tick(elapsedMs: number): GameOrchestratorEffects;
  handlePlayerAction(action: PlayerAction): GameOrchestratorEffects;
  handleScreenCommand(command: ScreenCommand): GameOrchestratorEffects;
  submitHighScoreName(name: string): GameOrchestratorEffects;
  handleLifecycle(event: BrowserLifecycleEvent): GameOrchestratorEffects;
  setPrompt(prompt: PromptScreen | null): GameOrchestratorEffects;
}

const NO_EFFECTS: GameOrchestratorEffects = { resetInput: false };
const RESET_INPUT_EFFECTS: GameOrchestratorEffects = { resetInput: true };

/** Creates the pure orchestration layer for a browser Tetris session. */
export function createGameOrchestrator(options: GameOrchestratorOptions = {}): GameOrchestrator {
  const storageAdapter = options.storageAdapter ?? createMemoryStorageAdapter();
  const stateMachine = createScreenStateMachine(options.initialScreenStack ?? getInitialScreenStack());
  const seedFactory = options.seedFactory ?? createRuntimeSeed;
  const nowIso = options.nowIso ?? (() => new Date().toISOString());

  let settings = loadSettings(storageAdapter);
  let highScores = loadHighScores(storageAdapter);
  let engine: GameEngine | null = null;
  let prompt: PromptScreen | null = null;
  let pendingHighScore: HighScoreCandidate | null = null;
  let gameOverRecorded = false;

  function snapshot(): GameOrchestratorSnapshot {
    const baseStack = stateMachine.snapshot();
    const screens = prompt ? [...baseStack.screens, prompt] : [...baseStack.screens];
    const screenStack: ScreenStackSnapshot = {
      screens,
      settings,
      highScores
    };
    const activeScreen = getActiveScreen(screenStack) ?? "splash";

    return {
      game: engine ? getState(engine) : null,
      screenStack,
      settings,
      highScores,
      pendingHighScore,
      activeScreen,
      prompt
    };
  }

  function startNewGame(): GameOrchestratorEffects {
    const gameConfig = {
      seed: seedFactory(),
      startingLevel: 1,
      ghostEnabled: settings.ghostEnabled,
      nextPieceCount: settings.nextPieceCount
    };
    if (options.initialBoard) {
      Object.assign(gameConfig, { initialBoard: options.initialBoard });
    }
    engine = initGame(gameConfig);
    gameOverRecorded = false;
    pendingHighScore = null;
    stateMachine.dispatch({ type: "reset", screen: "gameplay" });
    const gameOverEffects = observeGameOver();
    return gameOverEffects.resetInput ? gameOverEffects : RESET_INPUT_EFFECTS;
  }

  function pauseGame(): GameOrchestratorEffects {
    if (engine && isBaseScreen("gameplay")) {
      tickEngine(engine, 0);
      const gameOverEffects = observeGameOver();
      if (gameOverEffects.resetInput) {
        return gameOverEffects;
      }
    }
    if (isBaseScreen("gameplay")) {
      stateMachine.dispatch({ type: "push", screen: "pause" });
      return RESET_INPUT_EFFECTS;
    }
    return NO_EFFECTS;
  }

  function resumeGame(): GameOrchestratorEffects {
    if (isBaseScreen("pause")) {
      stateMachine.dispatch({ type: "pop" });
      return RESET_INPUT_EFFECTS;
    }
    return NO_EFFECTS;
  }

  function returnToMainMenu(): GameOrchestratorEffects {
    engine = null;
    gameOverRecorded = false;
    pendingHighScore = null;
    prompt = null;
    stateMachine.dispatch({ type: "reset", screen: "main-menu" });
    return RESET_INPUT_EFFECTS;
  }

  function updateSettings(nextSettings: UserSettings): GameOrchestratorEffects {
    settings = nextSettings;
    saveSettings(storageAdapter, settings);
    return NO_EFFECTS;
  }

  function observeGameOver(): GameOrchestratorEffects {
    if (!engine || gameOverRecorded) {
      return NO_EFFECTS;
    }

    const state = getState(engine);
    if (state.phase !== "game-over") {
      return NO_EFFECTS;
    }

    gameOverRecorded = true;
    const candidate: HighScoreCandidate = {
      score: state.score.score,
      lines: state.score.lines,
      level: state.score.level,
      achievedAtIso: nowIso()
    };

    pendingHighScore = isQualifyingHighScore(highScores, candidate) ? candidate : null;
    stateMachine.dispatch({ type: "reset", screen: "gameplay" });
    stateMachine.dispatch({ type: "push", screen: pendingHighScore ? "high-score-entry" : "game-over" });
    return RESET_INPUT_EFFECTS;
  }

  function submitHighScoreName(name: string): GameOrchestratorEffects {
    if (!pendingHighScore) {
      return NO_EFFECTS;
    }

    highScores = addHighScore(highScores, {
      ...pendingHighScore,
      name
    });
    saveHighScores(storageAdapter, highScores);
    pendingHighScore = null;
    stateMachine.dispatch({ type: "reset", screen: "gameplay" });
    stateMachine.dispatch({ type: "push", screen: "game-over" });
    return RESET_INPUT_EFFECTS;
  }

  function isBaseScreen(screen: ScreenId): boolean {
    return stateMachine.current === screen;
  }

  function handleScreenCommand(command: ScreenCommand): GameOrchestratorEffects {
    switch (command) {
      case "advance-splash":
        stateMachine.dispatch({ type: "reset", screen: "main-menu" });
        return RESET_INPUT_EFFECTS;
      case "start-game":
        return startNewGame();
      case "pause-game":
        return pauseGame();
      case "show-high-scores":
        stateMachine.dispatch({ type: "reset", screen: "high-scores" });
        return RESET_INPUT_EFFECTS;
      case "show-settings":
        stateMachine.dispatch({ type: "reset", screen: "settings" });
        return RESET_INPUT_EFFECTS;
      case "resume-game":
        return resumeGame();
      case "restart-game":
      case "retry-game":
        return startNewGame();
      case "main-menu":
      case "back":
        return returnToMainMenu();
      case "toggle-ghost":
        return updateSettings({ ...settings, ghostEnabled: !settings.ghostEnabled });
      case "toggle-next":
        return updateSettings({ ...settings, nextPieceCount: settings.nextPieceCount === 1 ? 3 : 1 });
      case "toggle-sound":
        return updateSettings({ ...settings, soundEnabled: !settings.soundEnabled });
    }
  }

  function setPrompt(nextPrompt: PromptScreen | null): GameOrchestratorEffects {
    if (prompt === nextPrompt) {
      return NO_EFFECTS;
    }
    prompt = nextPrompt;
    return RESET_INPUT_EFFECTS;
  }

  return {
    snapshot,

    tick(elapsedMs: number): GameOrchestratorEffects {
      if (engine && prompt === null && isBaseScreen("gameplay")) {
        tickEngine(engine, elapsedMs);
        return observeGameOver();
      }
      return NO_EFFECTS;
    },

    handlePlayerAction(action: PlayerAction): GameOrchestratorEffects {
      if (prompt !== null) {
        return action.type === "pause-toggle" ? pauseGame() : NO_EFFECTS;
      }

      switch (stateMachine.current) {
        case "splash":
          return handleScreenCommand("advance-splash");
        case "main-menu":
          return NO_EFFECTS;
        case "high-scores":
        case "settings":
          return action.type === "pause-toggle" || action.type === "menu-back"
            ? handleScreenCommand("back")
            : NO_EFFECTS;
        case "high-score-entry":
          return NO_EFFECTS;
        case "pause":
          return action.type === "pause-toggle" ? resumeGame() : NO_EFFECTS;
        case "game-over":
          return action.type === "pause-toggle" || action.type === "menu-back"
            ? returnToMainMenu()
            : NO_EFFECTS;
        case "gameplay":
          if (action.type === "pause-toggle") {
            return pauseGame();
          }
          if (engine) {
            injectInput(engine, action);
          }
          return NO_EFFECTS;
        case "rotate-prompt":
        case "widen-prompt":
          return NO_EFFECTS;
      }
    },

    handleScreenCommand,

    submitHighScoreName,

    handleLifecycle(event: BrowserLifecycleEvent): GameOrchestratorEffects {
      switch (event) {
        case "visibility-hidden":
        case "window-blur":
          return pauseGame();
        case "orientation-restricted":
          return setPrompt("rotate-prompt");
        case "orientation-restored":
          return prompt === "rotate-prompt" ? setPrompt(null) : NO_EFFECTS;
        case "visibility-visible":
        case "window-focus":
          return NO_EFFECTS;
      }
    },

    setPrompt
  };
}

/** Creates the browser application shell around an existing canvas element. */
export function createApp(options: AppBootOptions): AppRuntime {
  const storageAdapter = options.storageAdapter ?? createBrowserStorageAdapter();
  const orchestratorOptions: GameOrchestratorOptions = { storageAdapter };
  if (options.seedFactory) {
    Object.assign(orchestratorOptions, { seedFactory: options.seedFactory });
  }
  if (options.nowIso) {
    Object.assign(orchestratorOptions, { nowIso: options.nowIso });
  }
  const orchestrator = createGameOrchestrator(orchestratorOptions);
  const audioEngine = createAudioEngine({ soundEnabled: orchestrator.snapshot().settings.soundEnabled });
  const themeAssetsLoader = options.themeAssetsLoader ?? loadNeonThemeAssets;
  const loadingNotice = createGameLoadingNotice();

  let stopped = false;
  let renderer: CanvasRenderer | null = null;
  let rafId: number | null = null;
  let lastRafTimestampMs: number | null = null;
  let splashTimerId: number | null = null;
  let touchInput: TouchInputSubscription | null = null;
  let keyboardInput: KeyboardInputSubscription | null = null;
  let lifecycleSubscription: BrowserLifecycleSubscription | null = null;
  let latestLayout: GameLayout | null = null;
  // Layout reads include viewport, device pixel ratio, and safe-area probes;
  // cache until a lifecycle or resize event invalidates them.
  let cachedLayout: GameLayout | null = null;
  let layoutDirty = true;
  // RAF still advances game time every frame, but Canvas rendering is gated by
  // visible-state changes because most ticks do not move a piece.
  let renderDirty = true;
  let lastRenderedSignature: string | null = null;
  let renderAnimationUntilMs = 0;
  let lastSoundLockKey: string | null = null;
  let lastSoundPhase: string | null = null;
  let lastSoundLevel = 1;
  let hardDropVisual: RenderVisualEvents["hardDrop"] = null;
  const highScoreNamePrompt = createHighScoreNamePrompt((name) => {
    applyEffects(orchestrator.submitHighScoreName(name));
    audioEngine.play("menu-select");
    renderFrame();
  });

  const resetInput = (): void => {
    touchInput?.reset(window.performance.now());
    keyboardInput?.reset();
  };

  const applyEffects = (effects: GameOrchestratorEffects): void => {
    if (effects.resetInput) {
      resetInput();
    }
  };

  const invalidateLayout = (): void => {
    layoutDirty = true;
    latestLayout = null;
    requestRender();
  };

  const requestRender = (): void => {
    renderDirty = true;
  };

  const getCurrentLayout = (): GameLayout => {
    if (layoutDirty || cachedLayout === null) {
      cachedLayout = createCurrentLayout();
      layoutDirty = false;
    }
    return cachedLayout;
  };

  const getTouchHorizontalCellSizePt = (): number => {
    const layout = getCurrentLayout();
    return layout.mode === "iphone-portrait" ? layout.cellSizePx : 0;
  };

  const renderFrame = (force = true): void => {
    if (!renderer) {
      return;
    }

    const nowMs = window.performance.now();
    const layout = getCurrentLayout();
    latestLayout = layout;
    applyEffects(orchestrator.setPrompt(promptForLayout(layout)));
    const snapshot = orchestrator.snapshot();
    audioEngine.setSettings({ soundEnabled: snapshot.settings.soundEnabled });
    audioEngine.setMusicActive(isBackgroundMusicScreen(snapshot.activeScreen));
    updateRenderAnimationDeadline(snapshot, nowMs);
    observeSoundCues(snapshot);
    const signature = createRenderSignature(snapshot, layout, hardDropVisual);
    // Input/screen commands force a draw; RAF ticks draw only when visible
    // state changes or an effect is still aging.
    const shouldRender = force || renderDirty || signature !== lastRenderedSignature || renderAnimationUntilMs > 0;
    highScoreNamePrompt.sync(snapshot);
    if (!shouldRender) {
      expireVisualEvents(nowMs);
      return;
    }

    renderer.render({
      game: snapshot.game,
      layout,
      screenStack: snapshot.screenStack,
      visualEvents: { hardDrop: hardDropVisual },
      nowMs
    });
    lastRenderedSignature = signature;
    renderDirty = false;
    expireVisualEvents(nowMs);
  };

  const dispatchAction = (action: PlayerAction): void => {
    if (action.type === "hard-drop") {
      hardDropVisual = captureHardDropVisual(orchestrator.snapshot(), action.occurredAtMs);
    }
    playActionCue(action);
    applyEffects(orchestrator.handlePlayerAction(action));
    // Process queued input before the forced render so controls stay immediate
    // even when the next RAF has not run yet.
    applyEffects(orchestrator.tick(0));
    renderFrame();
  };

  const tickFrame = (timestampMs: number): void => {
    if (stopped || !renderer) {
      return;
    }

    const elapsedMs = lastRafTimestampMs === null ? 0 : timestampMs - lastRafTimestampMs;
    lastRafTimestampMs = timestampMs;
    applyEffects(orchestrator.tick(elapsedMs));
    renderFrame(false);
    rafId = window.requestAnimationFrame(tickFrame);
  };

  const handleResize = (): void => {
    resetInput();
    invalidateLayout();
    renderFrame();
  };

  const handleClick = (event: MouseEvent): void => {
    handleCanvasPoint(event.clientX, event.clientY, event);
  };

  const handleTouchEnd = (event: TouchEvent): void => {
    const touch = event.changedTouches[0];
    if (!touch) {
      return;
    }

    handleCanvasPoint(touch.clientX, touch.clientY, event);
  };

  const handleKeyDown = (event: KeyboardEvent): void => {
    if (event.defaultPrevented) {
      return;
    }

    if (event.code === "Enter") {
      const command = primaryCommandForScreen(orchestrator.snapshot().activeScreen);
      if (command) {
        event.preventDefault();
        audioEngine.play("menu-select");
        applyEffects(orchestrator.handleScreenCommand(command));
        renderFrame();
      }
    }
  };

  const handleAudioUnlock = (): void => {
    void audioEngine.unlock();
  };

  const handleCanvasPoint = (clientX: number, clientY: number, event: Event): void => {
    const rect = options.canvas.getBoundingClientRect();
    const xPx = clientX - rect.left;
    const yPx = clientY - rect.top;
    const snapshot = orchestrator.snapshot();
    const layout = latestLayout ?? getCurrentLayout();
    const gameplayCommand = hitTestGameplayCommand(snapshot, layout, xPx, yPx);
    const screenCommand =
      gameplayCommand ??
      hitTestScreenCommand(snapshot.activeScreen, rect.width, rect.height, xPx, yPx, snapshot.screenStack);

    if (!screenCommand) {
      return;
    }

    event.preventDefault();
    event.stopImmediatePropagation();
    audioEngine.play(commandSoundCue(screenCommand));
    applyEffects(orchestrator.handleScreenCommand(screenCommand));
    renderFrame();
  };

  const observeSoundCues = (snapshot: GameOrchestratorSnapshot): void => {
    const game = snapshot.game;
    if (!game) {
      lastSoundLockKey = null;
      lastSoundPhase = snapshot.activeScreen;
      lastSoundLevel = 1;
      hardDropVisual = null;
      return;
    }

    if (game.score.level > lastSoundLevel) {
      audioEngine.play("level-up");
    }
    lastSoundLevel = game.score.level;

    if (game.lastLock) {
      const lockKey = `${game.score.score}:${game.lastLock.piece}:${game.lastLock.awardedPoints}:${game.lastLock.clearedRows.join(".")}`;
      if (lockKey !== lastSoundLockKey) {
        lastSoundLockKey = lockKey;
        if (game.lastLock.clearedLines === 4) {
          audioEngine.play("tetris");
        } else if (game.lastLock.clearedLines > 0) {
          audioEngine.play(game.score.combo > 0 ? "combo" : "line-clear");
        } else {
          audioEngine.play("lock");
        }
      }
    }

    if (game.phase === "game-over" && lastSoundPhase !== "game-over") {
      audioEngine.play("game-over");
    }
    lastSoundPhase = game.phase;
  };

  const updateRenderAnimationDeadline = (snapshot: GameOrchestratorSnapshot, nowMs: number): void => {
    // Signature gating would otherwise stop drawing between state changes;
    // these deadlines keep renderer-owned fades alive.
    const game = snapshot.game;
    if (hardDropVisual) {
      renderAnimationUntilMs = Math.max(renderAnimationUntilMs, hardDropVisual.occurredAtMs + 170);
    }
    if (game?.lastLock && (game.lastLock.clearedLines > 0 || game.lastLock.awardedPoints > 0)) {
      renderAnimationUntilMs = Math.max(renderAnimationUntilMs, nowMs + 720);
    }
    if (game?.phase === "game-over" && lastSoundPhase !== "game-over") {
      renderAnimationUntilMs = Math.max(renderAnimationUntilMs, nowMs + 820);
    }
  };

  const expireVisualEvents = (nowMs: number): void => {
    if (hardDropVisual && nowMs - hardDropVisual.occurredAtMs > 170) {
      hardDropVisual = null;
    }
    if (renderAnimationUntilMs > 0 && nowMs >= renderAnimationUntilMs) {
      renderAnimationUntilMs = 0;
    }
  };

  const captureHardDropVisual = (
    snapshot: GameOrchestratorSnapshot,
    occurredAtMs: number
  ): RenderVisualEvents["hardDrop"] => {
    if (!snapshot.game?.activePiece) {
      return null;
    }
    return {
      piece: snapshot.game.activePiece,
      occurredAtMs
    };
  };

  const playActionCue = (action: PlayerAction): void => {
    switch (action.type) {
      case "move-left":
      case "move-right":
      case "horizontal-drag":
        audioEngine.play("move");
        break;
      case "rotate-cw":
      case "rotate-ccw":
        audioEngine.play("rotate");
        break;
      case "soft-drop-start":
        audioEngine.play("soft-drop");
        break;
      case "hard-drop":
        audioEngine.play("hard-drop");
        break;
      case "pause-toggle":
        audioEngine.play(orchestrator.snapshot().activeScreen === "pause" ? "resume" : "pause");
        break;
      case "restart":
      case "menu-back":
      case "soft-drop-stop":
      case "horizontal-drag-end":
        break;
    }
  };

  const commandSoundCue = (command: ScreenCommand): SoundCue => {
    switch (command) {
      case "pause-game":
        return "pause";
      case "resume-game":
        return "resume";
      case "advance-splash":
      case "start-game":
      case "show-high-scores":
      case "show-settings":
      case "restart-game":
      case "retry-game":
      case "main-menu":
      case "back":
      case "toggle-ghost":
      case "toggle-next":
      case "toggle-sound":
        return "menu-select";
    }
  };

  return {
    canvas: options.canvas,
    async start(): Promise<void> {
      stopped = false;
      loadingNotice.showLoading();
      let loadedThemeAssets: NeonThemeAssets | null = null;
      try {
        loadedThemeAssets = await themeAssetsLoader();
        if (stopped) {
          loadedThemeAssets.dispose();
          return;
        }
        renderer = createCanvasRenderer({
          canvas: options.canvas,
          themeAssets: loadedThemeAssets
        });
      } catch (error) {
        loadedThemeAssets?.dispose();
        stopped = true;
        loadingNotice.showError(formatGameLoadingError(error));
        return;
      }

      loadingNotice.hide();
      renderFrame();
      window.addEventListener("resize", handleResize);
      window.addEventListener("keydown", handleAudioUnlock);
      window.addEventListener("keydown", handleKeyDown);
      options.canvas.addEventListener("pointerdown", handleAudioUnlock, { passive: true });
      options.canvas.addEventListener("click", handleClick);
      options.canvas.addEventListener("touchend", handleTouchEnd, { passive: false });
      touchInput = attachTouchInput(options.canvas, createGestureRecognizer(), dispatchAction, {
        getHorizontalCellSizePt: getTouchHorizontalCellSizePt
      });
      keyboardInput = attachKeyboardInput(window, dispatchAction);
      lifecycleSubscription = attachBrowserLifecycle((event) => {
        invalidateLayout();
        applyEffects(orchestrator.handleLifecycle(event));
        renderFrame();
      });
      splashTimerId = window.setTimeout(() => {
        if (orchestrator.snapshot().activeScreen === "splash") {
          applyEffects(orchestrator.handleScreenCommand("advance-splash"));
          renderFrame();
        }
      }, 2000);
      rafId = window.requestAnimationFrame(tickFrame);
      if (options.registerServiceWorker ?? true) {
        await registerServiceWorker("./sw.js");
      }
    },
    resetInput,
    snapshot(): GameOrchestratorSnapshot {
      return orchestrator.snapshot();
    },
    stop(): void {
      stopped = true;
      if (rafId !== null) {
        window.cancelAnimationFrame(rafId);
        rafId = null;
      }
      if (splashTimerId !== null) {
        window.clearTimeout(splashTimerId);
        splashTimerId = null;
      }
      window.removeEventListener("resize", handleResize);
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keydown", handleAudioUnlock);
      options.canvas.removeEventListener("pointerdown", handleAudioUnlock);
      options.canvas.removeEventListener("click", handleClick);
      options.canvas.removeEventListener("touchend", handleTouchEnd);
      lifecycleSubscription?.dispose();
      lifecycleSubscription = null;
      touchInput?.dispose();
      touchInput = null;
      keyboardInput?.dispose();
      keyboardInput = null;
      highScoreNamePrompt.dispose();
      loadingNotice.dispose();
      audioEngine.dispose();
      renderer?.dispose();
      renderer = null;
    }
  };
}

/** Creates and starts the app shell. */
export async function bootstrapApp(options: AppBootOptions): Promise<AppRuntime> {
  const app = createApp(options);
  await app.start();
  return app;
}

interface GameLoadingNotice {
  showLoading(): void;
  showError(message: string): void;
  hide(): void;
  dispose(): void;
}

function createGameLoadingNotice(): GameLoadingNotice {
  const overlay = document.createElement("div");
  overlay.id = "game-loading-notice";
  overlay.setAttribute("role", "status");
  overlay.style.position = "fixed";
  overlay.style.inset = "0";
  overlay.style.display = "none";
  overlay.style.placeItems = "center";
  overlay.style.padding = "max(24px, var(--safe-top)) max(20px, var(--safe-right)) max(24px, var(--safe-bottom)) max(20px, var(--safe-left))";
  overlay.style.boxSizing = "border-box";
  overlay.style.background = "#050714";
  overlay.style.color = "#f5f5f5";
  overlay.style.zIndex = "30";
  overlay.style.touchAction = "none";
  overlay.style.fontFamily = "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";
  overlay.style.textAlign = "center";

  const panel = document.createElement("div");
  panel.style.width = "min(360px, calc(100vw - 40px))";
  panel.style.boxSizing = "border-box";
  panel.style.border = "1px solid rgba(0, 240, 240, 0.6)";
  panel.style.background = "rgba(4, 6, 18, 0.94)";
  panel.style.padding = "20px";

  const title = document.createElement("h1");
  title.style.margin = "0 0 12px";
  title.style.fontSize = "20px";
  title.style.fontWeight = "700";

  const detail = document.createElement("p");
  detail.style.margin = "0";
  detail.style.color = "#cfcfcf";
  detail.style.fontSize = "13px";
  detail.style.lineHeight = "1.45";
  detail.style.overflowWrap = "anywhere";

  panel.append(title, detail);
  overlay.append(panel);
  document.body.append(overlay);

  return {
    showLoading(): void {
      overlay.id = "game-loading-notice";
      overlay.dataset.state = "loading";
      overlay.setAttribute("role", "status");
      title.textContent = "LOADING GAME";
      detail.textContent = "Loading required visual assets.";
      overlay.style.display = "grid";
    },
    showError(message: string): void {
      overlay.id = "game-loading-error";
      overlay.dataset.state = "error";
      overlay.setAttribute("role", "alert");
      title.textContent = "GAME LOADING ERROR";
      detail.textContent = message;
      overlay.style.display = "grid";
    },
    hide(): void {
      overlay.style.display = "none";
    },
    dispose(): void {
      overlay.remove();
    }
  };
}

function formatGameLoadingError(error: unknown): string {
  if (error instanceof NeonThemeAssetLoadError) {
    const missingAssets = error.failures
      .slice(0, 3)
      .map((failure) => failure.src)
      .join(", ");
    const suffix = error.failures.length > 3 ? ` and ${error.failures.length - 3} more` : "";
    return `Required visual asset failed to load: ${missingAssets}${suffix}. Gameplay is disabled until the asset path is fixed.`;
  }

  return "Required visual assets could not be initialized. Gameplay is disabled until the loading error is fixed.";
}

interface HighScoreNamePrompt {
  sync(snapshot: GameOrchestratorSnapshot): void;
  dispose(): void;
}

function createHighScoreNamePrompt(onSubmit: (name: string) => void): HighScoreNamePrompt {
  const overlay = document.createElement("div");
  overlay.id = "high-score-name-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-labelledby", "high-score-name-title");
  overlay.style.position = "fixed";
  overlay.style.inset = "0";
  overlay.style.display = "none";
  overlay.style.placeItems = "center";
  overlay.style.padding = "max(24px, var(--safe-top)) max(20px, var(--safe-right)) max(24px, var(--safe-bottom)) max(20px, var(--safe-left))";
  overlay.style.boxSizing = "border-box";
  overlay.style.background = "rgba(0, 0, 0, 0.72)";
  overlay.style.zIndex = "20";
  overlay.style.touchAction = "auto";

  const form = document.createElement("form");
  form.style.width = "min(320px, calc(100vw - 40px))";
  form.style.boxSizing = "border-box";
  form.style.border = "1px solid #3a3a3a";
  form.style.background = "#151515";
  form.style.padding = "20px";
  form.style.fontFamily = "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";
  form.style.color = "#f5f5f5";

  const title = document.createElement("h1");
  title.id = "high-score-name-title";
  title.textContent = "NEW HIGH SCORE";
  title.style.margin = "0 0 12px";
  title.style.fontSize = "20px";
  title.style.textAlign = "center";
  title.style.fontWeight = "700";

  const scoreText = document.createElement("p");
  scoreText.dataset.highScoreSummary = "true";
  scoreText.style.margin = "0 0 14px";
  scoreText.style.color = "#cfcfcf";
  scoreText.style.fontSize = "14px";
  scoreText.style.textAlign = "center";

  const label = document.createElement("label");
  label.htmlFor = "high-score-name-input";
  label.textContent = "NAME";
  label.style.display = "block";
  label.style.margin = "0 0 6px";
  label.style.fontSize = "13px";
  label.style.color = "#cfcfcf";

  const input = document.createElement("input");
  input.id = "high-score-name-input";
  input.name = "name";
  input.type = "text";
  input.autocomplete = "off";
  input.autocapitalize = "characters";
  input.spellcheck = false;
  input.maxLength = 10;
  input.placeholder = "PLAYER";
  input.style.width = "100%";
  input.style.boxSizing = "border-box";
  input.style.border = "1px solid #3a3a3a";
  input.style.borderRadius = "0";
  input.style.background = "#0d0d0d";
  input.style.color = "#f5f5f5";
  input.style.padding = "11px 10px";
  input.style.font = "16px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";
  input.style.textAlign = "center";

  const button = document.createElement("button");
  button.type = "submit";
  button.textContent = "SAVE SCORE";
  button.dataset.command = "submit-high-score";
  button.style.width = "100%";
  button.style.margin = "14px 0 0";
  button.style.border = "1px solid #3a3a3a";
  button.style.borderRadius = "0";
  button.style.background = "#0d0d0d";
  button.style.color = "#f5f5f5";
  button.style.padding = "11px 10px";
  button.style.font = "15px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";

  form.append(title, scoreText, label, input, button);
  overlay.append(form);
  document.body.append(overlay);

  let visible = false;

  const stopPropagation = (event: Event): void => {
    event.stopPropagation();
  };
  const handleSubmit = (event: SubmitEvent): void => {
    event.preventDefault();
    event.stopPropagation();
    onSubmit(input.value);
  };

  overlay.addEventListener("keydown", stopPropagation);
  overlay.addEventListener("keyup", stopPropagation);
  overlay.addEventListener("pointerdown", stopPropagation);
  overlay.addEventListener("touchstart", stopPropagation, { passive: true });
  form.addEventListener("submit", handleSubmit);

  return {
    sync(snapshot: GameOrchestratorSnapshot): void {
      const shouldShow = snapshot.activeScreen === "high-score-entry" && snapshot.pendingHighScore !== null;
      if (shouldShow && snapshot.pendingHighScore) {
        scoreText.textContent =
          `SCORE ${formatInteger(snapshot.pendingHighScore.score)} / ` +
          `LVL ${snapshot.pendingHighScore.level} / ${snapshot.pendingHighScore.lines} LINES`;
      }

      if (visible === shouldShow) {
        return;
      }

      visible = shouldShow;
      overlay.style.display = shouldShow ? "grid" : "none";
      if (shouldShow) {
        input.value = "";
        window.setTimeout(() => input.focus(), 0);
      } else {
        input.blur();
      }
    },
    dispose(): void {
      form.removeEventListener("submit", handleSubmit);
      overlay.remove();
    }
  };
}

function createCurrentLayout(): GameLayout {
  return computeGameLayout({
    widthPx: window.innerWidth,
    heightPx: window.innerHeight,
    devicePixelRatio: window.devicePixelRatio,
    safeArea: readSafeAreaInsets(),
    deviceClass: inferDeviceClass()
  });
}

function promptForLayout(layout: GameLayout): PromptScreen | null {
  if (layout.mode === "rotate-prompt" || layout.mode === "widen-prompt") {
    return layout.mode;
  }
  return null;
}

/** Returns true for screens where background music should be audible. */
export function isBackgroundMusicScreen(screen: ScreenId): boolean {
  switch (screen) {
    case "main-menu":
    case "high-scores":
    case "settings":
    case "gameplay":
      return true;
    case "splash":
    case "pause":
    case "high-score-entry":
    case "game-over":
    case "rotate-prompt":
    case "widen-prompt":
      return false;
  }
}

function createRenderSignature(
  snapshot: GameOrchestratorSnapshot,
  layout: GameLayout,
  hardDropVisual: RenderVisualEvents["hardDrop"]
): string {
  // Keep this aligned with every value the renderer can make visible;
  // omissions can leave a stale frame when RAF drawing is skipped.
  return [
    createLayoutSignature(layout),
    snapshot.activeScreen,
    snapshot.prompt ?? "no-prompt",
    snapshot.screenStack.screens.join(">"),
    createSettingsSignature(snapshot.settings),
    createHighScoreSignature(snapshot.highScores),
    snapshot.pendingHighScore
      ? `${snapshot.pendingHighScore.score}:${snapshot.pendingHighScore.level}:${snapshot.pendingHighScore.lines}`
      : "no-pending-score",
    createGameSignature(snapshot.game),
    hardDropVisual ? `${createPieceSignature(hardDropVisual.piece)}:${Math.trunc(hardDropVisual.occurredAtMs)}` : "no-hard-drop"
  ].join("|");
}

function createLayoutSignature(layout: GameLayout): string {
  return [
    layout.mode,
    layout.canvasWidth,
    layout.canvasHeight,
    layout.backingScale,
    layout.hud.x,
    layout.hud.y,
    layout.hud.width,
    layout.hud.height,
    layout.board.x,
    layout.board.y,
    layout.board.width,
    layout.board.height,
    layout.sidebar.x,
    layout.sidebar.y,
    layout.sidebar.width,
    layout.sidebar.height
  ].join(":");
}

function createSettingsSignature(settings: UserSettings): string {
  return `${settings.ghostEnabled ? "ghost" : "no-ghost"}:${settings.nextPieceCount}:${settings.soundEnabled ? "sound" : "mute"}`;
}

function createHighScoreSignature(highScores: HighScoreTable): string {
  return highScores.entries
    .map((entry) => `${entry.name}:${entry.score}:${entry.level}:${entry.lines}:${entry.achievedAtIso}`)
    .join(",");
}

function createGameSignature(game: SerializableGameState | null): string {
  if (!game) {
    return "no-game";
  }

  return [
    game.phase,
    createBoardSignature(game),
    createPieceSignature(game.activePiece),
    createPieceSignature(game.ghostPiece),
    game.nextQueue.join(""),
    game.score.score,
    game.score.level,
    game.score.lines,
    game.score.combo,
    game.score.backToBackTetris ? "b2b" : "no-b2b",
    game.settings.ghostEnabled ? "ghost" : "no-ghost",
    game.settings.nextPieceCount,
    game.lastLock
      ? `${game.lastLock.piece}:${game.lastLock.clearedLines}:${game.lastLock.awardedPoints}:${game.lastLock.clearedRows.join(".")}`
      : "no-lock",
    game.gameOverReason ?? "no-game-over-reason"
  ].join(":");
}

function createBoardSignature(game: SerializableGameState): string {
  let signature = "";
  for (const cell of game.board.cells) {
    signature += cell.occupied ? cell.piece : ".";
  }
  return signature;
}

function createPieceSignature(piece: SerializableGameState["activePiece"]): string {
  return piece ? `${piece.kind}:${piece.rotation}:${piece.origin.col},${piece.origin.row}` : "no-piece";
}

function readSafeAreaInsets(): SafeAreaInsets {
  const rootStyle = window.getComputedStyle(document.documentElement);
  const customPropertyInsets: SafeAreaInsets = {
    top: parseCssPx(rootStyle.getPropertyValue("--safe-top")),
    right: parseCssPx(rootStyle.getPropertyValue("--safe-right")),
    bottom: parseCssPx(rootStyle.getPropertyValue("--safe-bottom")),
    left: parseCssPx(rootStyle.getPropertyValue("--safe-left"))
  };

  if (hasResolvedSafeAreaInsets(customPropertyInsets)) {
    return customPropertyInsets;
  }

  return readSafeAreaInsetsFromProbe();
}

function parseCssPx(value: string): number {
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function hasResolvedSafeAreaInsets(insets: SafeAreaInsets): boolean {
  return insets.top > 0 || insets.right > 0 || insets.bottom > 0 || insets.left > 0;
}

function readSafeAreaInsetsFromProbe(): SafeAreaInsets {
  const probe = getSafeAreaProbe();
  const style = window.getComputedStyle(probe);
  return {
    top: parseCssPx(style.paddingTop),
    right: parseCssPx(style.paddingRight),
    bottom: parseCssPx(style.paddingBottom),
    left: parseCssPx(style.paddingLeft)
  };
}

function getSafeAreaProbe(): HTMLElement {
  const existing = document.querySelector<HTMLElement>("[data-safe-area-probe]");
  if (existing) {
    return existing;
  }

  const probe = document.createElement("div");
  probe.dataset.safeAreaProbe = "true";
  probe.setAttribute("aria-hidden", "true");
  probe.style.position = "fixed";
  probe.style.inset = "0";
  probe.style.visibility = "hidden";
  probe.style.pointerEvents = "none";
  probe.style.contain = "strict";
  probe.style.boxSizing = "border-box";
  probe.style.overflow = "hidden";
  probe.style.padding = "var(--safe-top) var(--safe-right) var(--safe-bottom) var(--safe-left)";
  document.body.append(probe);
  return probe;
}

function inferDeviceClass(): LayoutDeviceClass {
  const isIphoneUserAgent = /\biPhone\b|\biPod\b/.test(window.navigator.userAgent);
  const hasCoarsePointer = window.matchMedia("(pointer: coarse)").matches;
  return isIphoneUserAgent || (hasCoarsePointer && window.innerWidth <= 430) ? "iphone" : "desktop";
}

function createBrowserStorageAdapter(): StorageAdapter {
  try {
    if (typeof window !== "undefined" && window.localStorage) {
      return createLocalStorageAdapter(window.localStorage);
    }
  } catch {
    return createMemoryStorageAdapter();
  }

  return createMemoryStorageAdapter();
}

function createRuntimeSeed(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

function formatInteger(value: number): string {
  return Math.trunc(value).toLocaleString("en-US");
}

function primaryCommandForScreen(screen: ScreenId): ScreenCommand | null {
  switch (screen) {
    case "splash":
      return "advance-splash";
    case "main-menu":
      return "start-game";
    case "pause":
      return "resume-game";
    case "game-over":
      return "retry-game";
    case "high-scores":
    case "settings":
      return "back";
    case "high-score-entry":
    case "gameplay":
    case "rotate-prompt":
    case "widen-prompt":
      return null;
  }
}

function hitTestGameplayCommand(
  snapshot: GameOrchestratorSnapshot,
  layout: GameLayout,
  xPx: number,
  yPx: number
): ScreenCommand | null {
  if (snapshot.activeScreen !== "gameplay") {
    return null;
  }

  const pauseButton = getPauseButtonRect(layout);
  if (
    pauseButton &&
    xPx >= pauseButton.x &&
    xPx <= pauseButton.x + pauseButton.width &&
    yPx >= pauseButton.y &&
    yPx <= pauseButton.y + pauseButton.height
  ) {
    return "pause-game";
  }

  return null;
}
