/**
 * Registers the service worker when the browser context supports it.
 */

/** Result returned by service worker registration attempts. */
export interface ServiceWorkerRegistrationResult {
  readonly supported: boolean;
  readonly registered: boolean;
  readonly registration?: ServiceWorkerRegistration;
  readonly error?: unknown;
}

/** Hooks used to surface waiting service-worker updates to the user. */
export interface ServiceWorkerUpdateOptions {
  readonly promptForUpdate?: () => boolean | Promise<boolean>;
}

/** Registers the PWA service worker for HTTP(S) browser contexts. */
export async function registerServiceWorker(
  scriptUrl: string,
  options: ServiceWorkerUpdateOptions = {}
): Promise<ServiceWorkerRegistrationResult> {
  if (!("serviceWorker" in navigator)) {
    return { supported: false, registered: false };
  }

  if (location.protocol !== "http:" && location.protocol !== "https:") {
    return { supported: true, registered: false };
  }

  try {
    const registration = await navigator.serviceWorker.register(scriptUrl);
    wireUpdatePrompt(registration, options.promptForUpdate ?? promptForUpdate);
    void registration.update();
    return { supported: true, registered: true, registration };
  } catch (error: unknown) {
    return { supported: true, registered: false, error };
  }
}

function wireUpdatePrompt(
  registration: ServiceWorkerRegistration,
  prompt: () => boolean | Promise<boolean>
): void {
  let reloadAfterControllerChange = false;

  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (reloadAfterControllerChange) {
      window.location.reload();
    }
  });

  const requestActivation = async (worker: ServiceWorker): Promise<void> => {
    const shouldActivate = await prompt();
    if (!shouldActivate) {
      return;
    }
    reloadAfterControllerChange = true;
    worker.postMessage({ type: "SKIP_WAITING" });
  };

  if (registration.waiting && navigator.serviceWorker.controller) {
    void requestActivation(registration.waiting);
  }

  registration.addEventListener("updatefound", () => {
    const installingWorker = registration.installing;
    if (!installingWorker) {
      return;
    }

    installingWorker.addEventListener("statechange", () => {
      if (installingWorker.state === "installed" && navigator.serviceWorker.controller) {
        void requestActivation(installingWorker);
      }
    });
  });
}

function promptForUpdate(): boolean {
  return window.confirm("A new version of Agentic Tetris is available. Reload now?");
}
