/**
 * Owns SRS rotation and wall-kick contracts for pure game logic.
 */
import { canPlacePiece } from "./board";
import type { Board } from "./board";
import type { ActivePiece, RotationState, TetrominoKind } from "./pieces";

/** Rotation direction requested by a player action. */
export type RotationDirection = "cw" | "ccw";

/** One wall-kick test offset in board coordinates. */
export interface WallKickOffset {
  readonly deltaCol: number;
  readonly deltaRow: number;
}

/** Result of attempting a rotation. */
export interface RotationAttempt {
  readonly accepted: boolean;
  readonly piece: ActivePiece;
  readonly testedOffsets: readonly WallKickOffset[];
}

type RotationTransition = "0>R" | "R>0" | "R>2" | "2>R" | "2>L" | "L>2" | "L>0" | "0>L";

const STATE_ORDER: readonly RotationState[] = ["0", "R", "2", "L"];

const JLSTZ_WALL_KICKS: Readonly<Record<RotationTransition, readonly WallKickOffset[]>> = {
  "0>R": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [-1, 1],
    [0, -2],
    [-1, -2]
  ]),
  "R>0": convertGddOffsets([
    [0, 0],
    [1, 0],
    [1, -1],
    [0, 2],
    [1, 2]
  ]),
  "R>2": convertGddOffsets([
    [0, 0],
    [1, 0],
    [1, 1],
    [0, -2],
    [1, -2]
  ]),
  "2>R": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [-1, -1],
    [0, 2],
    [-1, 2]
  ]),
  "2>L": convertGddOffsets([
    [0, 0],
    [1, 0],
    [1, 1],
    [0, -2],
    [1, -2]
  ]),
  "L>2": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [-1, -1],
    [0, 2],
    [-1, 2]
  ]),
  "L>0": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [-1, 1],
    [0, -2],
    [-1, -2]
  ]),
  "0>L": convertGddOffsets([
    [0, 0],
    [1, 0],
    [1, -1],
    [0, 2],
    [1, 2]
  ])
};

const I_WALL_KICKS: Readonly<Record<RotationTransition, readonly WallKickOffset[]>> = {
  "0>R": convertGddOffsets([
    [0, 0],
    [-2, 0],
    [1, 0],
    [-2, -1],
    [1, 2]
  ]),
  "R>0": convertGddOffsets([
    [0, 0],
    [2, 0],
    [-1, 0],
    [2, 1],
    [-1, -2]
  ]),
  "R>2": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [2, 0],
    [-1, 2],
    [2, -1]
  ]),
  "2>R": convertGddOffsets([
    [0, 0],
    [1, 0],
    [-2, 0],
    [1, -2],
    [-2, 1]
  ]),
  "2>L": convertGddOffsets([
    [0, 0],
    [2, 0],
    [-1, 0],
    [2, -1],
    [-1, 2]
  ]),
  "L>2": convertGddOffsets([
    [0, 0],
    [-2, 0],
    [1, 0],
    [-2, 1],
    [1, -2]
  ]),
  "L>0": convertGddOffsets([
    [0, 0],
    [1, 0],
    [-2, 0],
    [1, 2],
    [-2, -1]
  ]),
  "0>L": convertGddOffsets([
    [0, 0],
    [-1, 0],
    [2, 0],
    [-1, -2],
    [2, 1]
  ])
};

/** Returns the next SRS rotation state for a direction. */
export function getNextRotationState(state: RotationState, direction: RotationDirection): RotationState {
  const index = STATE_ORDER.indexOf(state);
  const nextIndex = direction === "cw" ? (index + 1) % STATE_ORDER.length : (index + STATE_ORDER.length - 1) % STATE_ORDER.length;
  const nextState = STATE_ORDER[nextIndex];
  if (nextState === undefined) {
    throw new RangeError(`Unknown rotation state: ${state}`);
  }

  return nextState;
}

/** Attempts to rotate an active piece against a board. */
export function tryRotatePiece(board: Board, piece: ActivePiece, direction: RotationDirection): RotationAttempt {
  if (piece.kind === "O") {
    return {
      accepted: true,
      piece,
      testedOffsets: []
    };
  }

  const nextRotation = getNextRotationState(piece.rotation, direction);
  const offsets = getWallKickOffsets(piece.kind, piece.rotation, nextRotation);

  for (const offset of offsets) {
    const candidate: ActivePiece = {
      ...piece,
      rotation: nextRotation,
      origin: {
        col: piece.origin.col + offset.deltaCol,
        row: piece.origin.row + offset.deltaRow
      }
    };

    if (canPlacePiece(board, candidate)) {
      return {
        accepted: true,
        piece: candidate,
        testedOffsets: offsets
      };
    }
  }

  return {
    accepted: false,
    piece,
    testedOffsets: offsets
  };
}

/** Returns gameplay-spec SRS wall-kick offsets converted into board row coordinates. */
export function getWallKickOffsets(
  kind: TetrominoKind,
  from: RotationState,
  to: RotationState
): readonly WallKickOffset[] {
  if (kind === "O" || from === to) {
    return [];
  }

  const transition = `${from}>${to}` as RotationTransition;
  return kind === "I" ? I_WALL_KICKS[transition] : JLSTZ_WALL_KICKS[transition];
}

function convertGddOffsets(offsets: readonly (readonly [number, number])[]): readonly WallKickOffset[] {
  return offsets.map(([deltaCol, gddDeltaRow]) => {
    return {
      deltaCol,
      deltaRow: -gddDeltaRow
    };
  });
}
