/**
 * Provides contracts for stack-based screen state management.
 */
import type { ScreenId, ScreenStackSnapshot, ScreenTransition } from "./screens";

/** State machine responsible for app screens and overlays. */
export interface ScreenStateMachine {
  readonly current: ScreenId;
  dispatch(transition: ScreenTransition): ScreenStackSnapshot;
  snapshot(): ScreenStackSnapshot;
}

/** Creates the screen state machine used by the app shell. */
export function createScreenStateMachine(initial: ScreenStackSnapshot): ScreenStateMachine {
  let stack = [...initial.screens];

  return {
    get current(): ScreenId {
      return stack[stack.length - 1] ?? "splash";
    },
    dispatch(transition: ScreenTransition): ScreenStackSnapshot {
      switch (transition.type) {
        case "push":
          stack = [...stack, transition.screen];
          break;
        case "replace":
          stack = [...stack.slice(0, -1), transition.screen];
          break;
        case "pop":
          stack = stack.length > 1 ? stack.slice(0, -1) : stack;
          break;
        case "reset":
          stack = [transition.screen];
          break;
      }
      return { screens: stack };
    },
    snapshot(): ScreenStackSnapshot {
      return { screens: stack };
    }
  };
}
