/**
 * Provides render colors locked by the visual spec.
 */
import type { TetrominoKind } from "../core/pieces";

/** Tetromino color table. */
export type TetrominoPalette = Readonly<Record<TetrominoKind, string>>;

/** Canvas colors used outside tetromino blocks. */
export interface CanvasPalette {
  readonly background: string;
  readonly gridLine: string;
  readonly blockInset: string;
  readonly hudText: string;
  readonly hudMutedText: string;
  readonly panelFill: string;
  readonly panelStroke: string;
  readonly overlayFill: string;
}

export const TETROMINO_COLORS: TetrominoPalette = {
  I: "#00f0f0",
  O: "#f0f000",
  T: "#a000f0",
  S: "#00f000",
  Z: "#f00000",
  J: "#0000f0",
  L: "#f0a000"
};

export const CANVAS_COLORS: CanvasPalette = {
  background: "#050714",
  gridLine: "#263f8f",
  blockInset: "#050713",
  hudText: "#f5f5f5",
  hudMutedText: "#9bb6ff",
  panelFill: "#050713",
  panelStroke: "#3559c7",
  overlayFill: "rgba(3, 4, 14, 0.76)"
};

/** Returns the locked render color for a tetromino kind. */
export function getTetrominoColor(kind: TetrominoKind): string {
  return TETROMINO_COLORS[kind];
}

/** Returns the darker inset stroke color for a tetromino block. */
export function getBlockInsetColor(kind: TetrominoKind): string {
  return darkenHex(TETROMINO_COLORS[kind], 0.45);
}

/** Returns the non-piece canvas palette. */
export function getCanvasPalette(): CanvasPalette {
  return CANVAS_COLORS;
}

function darkenHex(hex: string, multiplier: number): string {
  const normalized = hex.replace("#", "");
  const red = parseInt(normalized.slice(0, 2), 16);
  const green = parseInt(normalized.slice(2, 4), 16);
  const blue = parseInt(normalized.slice(4, 6), 16);

  return `#${toHex(red * multiplier)}${toHex(green * multiplier)}${toHex(blue * multiplier)}`;
}

function toHex(value: number): string {
  return Math.max(0, Math.min(255, Math.floor(value))).toString(16).padStart(2, "0");
}
