/**
 * Declares high-level screen names and transition requests for the app shell.
 */
import type { HighScoreTable } from "../storage/high-scores";
import type { UserSettings } from "../storage/settings";

/** All screens and prompts named by the UX spec. */
export type ScreenId =
  | "splash"
  | "main-menu"
  | "gameplay"
  | "pause"
  | "high-score-entry"
  | "game-over"
  | "high-scores"
  | "settings"
  | "rotate-prompt"
  | "widen-prompt";

/** A request to change the active screen stack. */
export type ScreenTransition =
  | { readonly type: "push"; readonly screen: ScreenId }
  | { readonly type: "replace"; readonly screen: ScreenId }
  | { readonly type: "pop" }
  | { readonly type: "reset"; readonly screen: ScreenId };

/** Snapshot of active screens from bottom to top. */
export interface ScreenStackSnapshot {
  readonly screens: readonly ScreenId[];
  readonly settings?: UserSettings;
  readonly highScores?: HighScoreTable;
}

/** Returns the initial screen stack for a cold app launch. */
export function getInitialScreenStack(): ScreenStackSnapshot {
  return { screens: ["splash"] };
}

/** Commands that screen menus can request from app orchestration. */
export type ScreenCommand =
  | "advance-splash"
  | "start-game"
  | "pause-game"
  | "show-high-scores"
  | "show-settings"
  | "resume-game"
  | "restart-game"
  | "main-menu"
  | "retry-game"
  | "back"
  | "toggle-ghost"
  | "toggle-next"
  | "toggle-sound";

/** Menu item model shared by screen rendering and pointer hit testing. */
export interface ScreenMenuItem {
  readonly label: string;
  readonly command: ScreenCommand | null;
  readonly muted: boolean;
}

/** Menu layout rectangle for one rendered item. */
export interface ScreenMenuItemRect {
  readonly item: ScreenMenuItem;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** Menu layout model shared by screen rendering and hit testing. */
export interface ScreenMenuLayout {
  readonly title: string;
  readonly panelX: number;
  readonly panelY: number;
  readonly panelWidth: number;
  readonly panelHeight: number;
  readonly items: readonly ScreenMenuItemRect[];
}

/** Context needed to format screen-specific menu data. */
export interface ScreenMenuContext {
  readonly settings?: UserSettings;
  readonly highScores?: HighScoreTable;
}

const ITEM_HEIGHT_PX = 38;
const ITEM_GAP_PX = 10;
const TITLE_HEIGHT_PX = 52;
const PANEL_VERTICAL_PADDING_PX = 32;
const PANEL_HORIZONTAL_MARGIN_PX = 48;
const ITEM_HORIZONTAL_INSET_PX = 20;
const ITEM_TOP_OFFSET_PX = TITLE_HEIGHT_PX + 16;

/** Returns the active screen, or null for an empty stack. */
export function getActiveScreen(screenStack: ScreenStackSnapshot): ScreenId | null {
  return screenStack.screens[screenStack.screens.length - 1] ?? null;
}

/** Returns the menu title rendered for a screen. */
export function getScreenTitle(screen: ScreenId): string {
  switch (screen) {
    case "splash":
      return "AGENTIC TETRIS";
    case "main-menu":
      return "AGENTIC TETRIS";
    case "gameplay":
      return "";
    case "pause":
      return "PAUSED";
    case "high-score-entry":
      return "NEW HIGH SCORE";
    case "game-over":
      return "GAME OVER";
    case "high-scores":
      return "HIGH SCORES";
    case "settings":
      return "SETTINGS";
    case "rotate-prompt":
      return "ROTATE TO PORTRAIT";
    case "widen-prompt":
      return "WIDEN WINDOW";
  }
}

/** Returns menu items for a screen. */
export function getScreenMenuItems(screen: ScreenId, context: ScreenMenuContext = {}): readonly ScreenMenuItem[] {
  switch (screen) {
    case "splash":
    case "gameplay":
    case "high-score-entry":
    case "rotate-prompt":
    case "widen-prompt":
      return [];
    case "main-menu":
      return [
        createMenuItem("START GAME", "start-game"),
        createMenuItem("HIGH SCORES", "show-high-scores"),
        createMenuItem("SETTINGS", "show-settings")
      ];
    case "pause":
      return [
        createMenuItem("RESUME", "resume-game"),
        createMenuItem("RESTART", "restart-game"),
        createMenuItem("MAIN MENU", "main-menu")
      ];
    case "game-over":
      return [
        createMenuItem("RETRY", "retry-game"),
        createMenuItem("MAIN MENU", "main-menu")
      ];
    case "high-scores":
      return createHighScoreItems(context.highScores);
    case "settings":
      return createSettingsItems(context.settings);
  }
}

/** Computes the menu layout used by the Canvas screen renderer. */
export function computeScreenMenuLayout(
  screen: ScreenId,
  widthPx: number,
  heightPx: number,
  context: ScreenMenuContext = {}
): ScreenMenuLayout {
  const items = getScreenMenuItems(screen, context);
  const panelWidth = Math.min(320, Math.max(240, widthPx - PANEL_HORIZONTAL_MARGIN_PX));
  const panelHeight =
    TITLE_HEIGHT_PX +
    items.length * ITEM_HEIGHT_PX +
    Math.max(0, items.length - 1) * ITEM_GAP_PX +
    PANEL_VERTICAL_PADDING_PX;
  const panelX = Math.floor((widthPx - panelWidth) / 2);
  const panelY = Math.floor((heightPx - panelHeight) / 2);
  const itemWidth = panelWidth - ITEM_HORIZONTAL_INSET_PX * 2;

  return {
    title: getScreenTitle(screen),
    panelX,
    panelY,
    panelWidth,
    panelHeight,
    items: items.map((item, index) => {
      return {
        item,
        x: panelX + ITEM_HORIZONTAL_INSET_PX,
        y: panelY + ITEM_TOP_OFFSET_PX + index * (ITEM_HEIGHT_PX + ITEM_GAP_PX),
        width: itemWidth,
        height: ITEM_HEIGHT_PX
      };
    })
  };
}

/** Returns a command for a screen point if it hits an actionable menu item. */
export function hitTestScreenCommand(
  screen: ScreenId,
  widthPx: number,
  heightPx: number,
  xPx: number,
  yPx: number,
  context: ScreenMenuContext = {}
): ScreenCommand | null {
  if (screen === "splash") {
    return "advance-splash";
  }

  const layout = computeScreenMenuLayout(screen, widthPx, heightPx, context);
  for (const itemRect of layout.items) {
    if (
      itemRect.item.command !== null &&
      xPx >= itemRect.x &&
      xPx <= itemRect.x + itemRect.width &&
      yPx >= itemRect.y &&
      yPx <= itemRect.y + itemRect.height
    ) {
      return itemRect.item.command;
    }
  }

  return null;
}

/** Returns true when a screen should render as a prompt overlay. */
export function isPromptScreen(screen: ScreenId): boolean {
  return screen === "rotate-prompt" || screen === "widen-prompt";
}

function createMenuItem(label: string, command: ScreenCommand | null, muted = false): ScreenMenuItem {
  return { label, command, muted };
}

function createHighScoreItems(table: HighScoreTable | undefined): readonly ScreenMenuItem[] {
  const entries = table?.entries ?? [];
  const header = createMenuItem("RANK PLAYER NAME SCORE DATE", null, true);
  const scoreItems =
    entries.length === 0
      ? [createMenuItem("NO SCORES", null, true)]
      : entries.slice(0, 10).map((entry, index) => {
          const rank = String(index + 1).padStart(2, "0");
          return createMenuItem(`${rank} ${entry.name} ${formatInteger(entry.score)} ${formatHighScoreDate(entry.achievedAtIso)}`, null, true);
        });

  return [header, ...scoreItems, createMenuItem("BACK", "back")];
}

function createSettingsItems(settings: UserSettings | undefined): readonly ScreenMenuItem[] {
  const resolvedSettings: UserSettings = settings ?? {
    ghostEnabled: true,
    nextPieceCount: 1,
    soundEnabled: true
  };

  return [
    createMenuItem(`GHOST ${resolvedSettings.ghostEnabled ? "ON" : "OFF"}`, "toggle-ghost"),
    createMenuItem(`NEXT ${resolvedSettings.nextPieceCount}`, "toggle-next"),
    createMenuItem(`SOUND ${resolvedSettings.soundEnabled ? "ON" : "OFF"}`, "toggle-sound"),
    createMenuItem("BACK", "back")
  ];
}

function formatInteger(value: number): string {
  return Math.max(0, Math.trunc(value)).toLocaleString("en-US");
}

function formatHighScoreDate(achievedAtIso: string): string {
  const timestamp = Date.parse(achievedAtIso);
  if (Number.isNaN(timestamp)) {
    return "----------";
  }
  return new Date(timestamp).toISOString().slice(0, 10);
}
