/**
 * Defines the browser audio engine for sound effects and background music.
 */

/** Sound events that gameplay and UI modules may request. */
export type SoundCue =
  | "move"
  | "rotate"
  | "soft-drop"
  | "hard-drop"
  | "lock"
  | "line-clear"
  | "tetris"
  | "combo"
  | "level-up"
  | "game-over"
  | "menu-select"
  | "pause"
  | "resume";

/** Audio settings owned by the browser audio layer. */
export interface AudioSettings {
  readonly soundEnabled: boolean;
}

/** Browser audio engine handle. */
export interface AudioEngine {
  unlock(): Promise<void>;
  play(cue: SoundCue): void;
  setSettings(settings: AudioSettings): void;
  setMusicActive(active: boolean): void;
  dispose(): void;
}

/** Values supported by browser media preloading. */
export type MusicPreload = "" | "auto" | "metadata" | "none";

/** Minimal browser media element contract used for playlist music. */
export interface MusicPlayer {
  src: string;
  preload: MusicPreload;
  volume: number;
  addEventListener(type: "ended", listener: () => void): void;
  removeEventListener(type: "ended", listener: () => void): void;
  load(): void;
  pause(): void;
  play(): Promise<void>;
}

/** Optional hooks for tests and alternate music configuration. */
export interface AudioEngineOptions {
  readonly createMusicPlayer?: (src: string) => MusicPlayer | null;
  readonly musicTracks?: readonly string[];
  readonly musicVolume?: number;
}

/** Runtime music playlist. The first track is the first song played. */
export const DEFAULT_MUSIC_TRACKS = [
  "./assets/music/balalaika-dance-normal.mp3",
  "./assets/music/balalaika-dance-speed.mp3",
  "./assets/music/balkan-chip-normal.mp3",
  "./assets/music/balkan-chip-speed.mp3",
  "./assets/music/pocket-caravan-1.mp3",
  "./assets/music/pocket-caravan-2.mp3"
] as const;

const DEFAULT_MUSIC_VOLUME = 0.34;

/** Creates the browser audio engine. */
export function createAudioEngine(settings: AudioSettings, options: AudioEngineOptions = {}): AudioEngine {
  let currentSettings = settings;
  let context: AudioContext | null = null;
  let disposed = false;
  let musicActive = false;
  let musicPlayer: MusicPlayer | null = null;
  let musicTrackIndex = 0;
  let musicPlayPending = false;
  let musicPlaying = false;
  let musicBlockedUntilUnlock = false;
  let musicPlayToken = 0;

  const musicTracks = [...(options.musicTracks ?? DEFAULT_MUSIC_TRACKS)].filter((track) => track.length > 0);
  const createMusicPlayer = options.createMusicPlayer ?? createBrowserMusicPlayer;
  const musicVolume = options.musicVolume ?? DEFAULT_MUSIC_VOLUME;

  const ensureContext = (): AudioContext | null => {
    if (disposed || !currentSettings.soundEnabled) {
      return null;
    }
    if (context) {
      return context;
    }
    const Constructor = getAudioContextConstructor();
    if (!Constructor) {
      return null;
    }
    context = new Constructor();
    return context;
  };

  const ensureMusicPlayer = (): MusicPlayer | null => {
    if (disposed || musicTracks.length === 0) {
      return null;
    }
    if (musicPlayer) {
      return musicPlayer;
    }
    const track = musicTracks[musicTrackIndex];
    if (!track) {
      return null;
    }
    musicPlayer = createMusicPlayer(track);
    if (!musicPlayer) {
      return null;
    }
    musicPlayer.preload = "auto";
    musicPlayer.volume = musicVolume;
    musicPlayer.addEventListener("ended", handleMusicEnded);
    return musicPlayer;
  };

  const startMusic = (): void => {
    if (
      disposed ||
      !currentSettings.soundEnabled ||
      !musicActive ||
      musicPlaying ||
      musicPlayPending ||
      musicBlockedUntilUnlock
    ) {
      return;
    }

    const player = ensureMusicPlayer();
    if (!player) {
      return;
    }

    musicPlayPending = true;
    const token = musicPlayToken + 1;
    musicPlayToken = token;
    try {
      void player.play().then(
        () => {
          if (token !== musicPlayToken) {
            return;
          }
          musicPlayPending = false;
          musicPlaying = true;
        },
        () => {
          if (token !== musicPlayToken) {
            return;
          }
          musicPlayPending = false;
          musicPlaying = false;
          musicBlockedUntilUnlock = true;
        }
      );
    } catch {
      if (token === musicPlayToken) {
        musicPlayPending = false;
        musicPlaying = false;
        musicBlockedUntilUnlock = true;
      }
    }
  };

  const pauseMusic = (): void => {
    musicPlayToken += 1;
    musicPlayPending = false;
    musicPlaying = false;
    if (musicPlayer) {
      musicPlayer.pause();
    }
  };

  function handleMusicEnded(): void {
    musicPlayPending = false;
    musicPlaying = false;
    if (disposed || musicTracks.length === 0) {
      return;
    }

    musicTrackIndex = (musicTrackIndex + 1) % musicTracks.length;
    const nextTrack = musicTracks[musicTrackIndex];
    if (!nextTrack || !musicPlayer) {
      return;
    }

    musicPlayer.src = nextTrack;
    musicPlayer.load();
    startMusic();
  }

  return {
    async unlock(): Promise<void> {
      const audioContext = ensureContext();
      if (audioContext && audioContext.state === "suspended") {
        await audioContext.resume();
      }
      musicBlockedUntilUnlock = false;
      startMusic();
    },

    play(cue: SoundCue): void {
      const audioContext = context;
      if (disposed || !currentSettings.soundEnabled || !audioContext || audioContext.state === "suspended") {
        return;
      }
      playCue(audioContext, cue);
    },

    setSettings(nextSettings: AudioSettings): void {
      const wasSoundEnabled = currentSettings.soundEnabled;
      currentSettings = nextSettings;
      if (!currentSettings.soundEnabled) {
        pauseMusic();
        return;
      }
      if (!wasSoundEnabled) {
        musicBlockedUntilUnlock = false;
      }
      startMusic();
    },

    setMusicActive(active: boolean): void {
      if (musicActive === active) {
        startMusic();
        return;
      }

      musicActive = active;
      if (musicActive) {
        startMusic();
      } else {
        pauseMusic();
      }
    },

    dispose(): void {
      disposed = true;
      if (musicPlayer) {
        musicPlayer.removeEventListener("ended", handleMusicEnded);
        musicPlayer.pause();
        musicPlayer = null;
      }
      if (context && context.state !== "closed") {
        void context.close();
      }
      context = null;
    }
  };
}

type AudioContextConstructor = typeof AudioContext;

interface AudioWindow extends Window {
  readonly AudioContext?: AudioContextConstructor;
  readonly webkitAudioContext?: AudioContextConstructor;
}

interface ToneStep {
  readonly frequency: number;
  readonly durationMs: number;
  readonly type?: OscillatorType;
  readonly gain?: number;
}

function getAudioContextConstructor(): AudioContextConstructor | null {
  if (typeof window === "undefined") {
    return null;
  }
  const audioWindow = window as AudioWindow;
  return audioWindow.AudioContext ?? audioWindow.webkitAudioContext ?? null;
}

function createBrowserMusicPlayer(src: string): MusicPlayer | null {
  if (typeof Audio === "undefined") {
    return null;
  }

  const audio = new Audio(src);
  return {
    get src(): string {
      return audio.src;
    },
    set src(value: string) {
      audio.src = value;
    },
    get preload(): MusicPreload {
      return toMusicPreload(audio.preload);
    },
    set preload(value: MusicPreload) {
      audio.preload = value;
    },
    get volume(): number {
      return audio.volume;
    },
    set volume(value: number) {
      audio.volume = value;
    },
    addEventListener(type: "ended", listener: () => void): void {
      audio.addEventListener(type, listener);
    },
    removeEventListener(type: "ended", listener: () => void): void {
      audio.removeEventListener(type, listener);
    },
    load(): void {
      audio.load();
    },
    pause(): void {
      audio.pause();
    },
    play(): Promise<void> {
      return audio.play();
    }
  };
}

function toMusicPreload(value: string): MusicPreload {
  return value === "auto" || value === "metadata" || value === "none" ? value : "";
}

function playCue(context: AudioContext, cue: SoundCue): void {
  const steps = getCueSteps(cue);
  let offsetMs = 0;
  for (const step of steps) {
    scheduleTone(context, step, offsetMs);
    offsetMs += step.durationMs * 0.68;
  }
}

function scheduleTone(context: AudioContext, step: ToneStep, offsetMs: number): void {
  const now = context.currentTime + offsetMs / 1000;
  const duration = step.durationMs / 1000;
  const oscillator = context.createOscillator();
  const gain = context.createGain();
  oscillator.type = step.type ?? "square";
  oscillator.frequency.setValueAtTime(step.frequency, now);
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(step.gain ?? 0.045, now + 0.012);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
  oscillator.connect(gain);
  gain.connect(context.destination);
  oscillator.start(now);
  oscillator.stop(now + duration + 0.02);
}

function getCueSteps(cue: SoundCue): readonly ToneStep[] {
  switch (cue) {
    case "move":
      return [{ frequency: 180, durationMs: 34, gain: 0.025 }];
    case "rotate":
      return [{ frequency: 320, durationMs: 42, gain: 0.032 }];
    case "soft-drop":
      return [{ frequency: 120, durationMs: 26, type: "triangle", gain: 0.018 }];
    case "hard-drop":
      return [
        { frequency: 180, durationMs: 42, gain: 0.04 },
        { frequency: 82, durationMs: 70, type: "sawtooth", gain: 0.045 }
      ];
    case "lock":
      return [{ frequency: 96, durationMs: 56, type: "triangle", gain: 0.04 }];
    case "line-clear":
      return [
        { frequency: 392, durationMs: 50, gain: 0.035 },
        { frequency: 523, durationMs: 70, gain: 0.04 }
      ];
    case "tetris":
      return [
        { frequency: 392, durationMs: 60, gain: 0.045 },
        { frequency: 523, durationMs: 60, gain: 0.045 },
        { frequency: 784, durationMs: 100, gain: 0.05 }
      ];
    case "combo":
      return [
        { frequency: 330, durationMs: 40, gain: 0.032 },
        { frequency: 660, durationMs: 44, gain: 0.036 }
      ];
    case "level-up":
      return [
        { frequency: 262, durationMs: 70, type: "triangle", gain: 0.04 },
        { frequency: 392, durationMs: 70, type: "triangle", gain: 0.04 },
        { frequency: 784, durationMs: 120, type: "triangle", gain: 0.045 }
      ];
    case "game-over":
      return [
        { frequency: 220, durationMs: 90, type: "sawtooth", gain: 0.045 },
        { frequency: 165, durationMs: 110, type: "sawtooth", gain: 0.04 },
        { frequency: 110, durationMs: 160, type: "sawtooth", gain: 0.035 }
      ];
    case "menu-select":
      return [{ frequency: 440, durationMs: 36, gain: 0.028 }];
    case "pause":
      return [{ frequency: 196, durationMs: 80, type: "triangle", gain: 0.034 }];
    case "resume":
      return [{ frequency: 330, durationMs: 80, type: "triangle", gain: 0.034 }];
  }
}
