/**
 * Translates desktop keyboard events into named player actions.
 */
import type { DiscretePlayerActionType, PlayerAction } from "../core/actions";
import { createPlayerAction } from "../core/actions";
import { INPUT_REPEAT_TIMING } from "./repeat";

/** Minimal keyboard event shape used by the mapper and adapter. */
export interface KeyboardInputEvent {
  readonly code: string;
  readonly type: string;
  readonly repeat: boolean;
}

/** Keyboard binding for one player action. */
export interface KeyboardBinding {
  readonly code: string;
  readonly action: DiscretePlayerActionType;
  readonly repeats: boolean;
}

/** Subscription returned by keyboard input attachment. */
export interface KeyboardInputSubscription {
  reset(): void;
  dispose(): void;
}

export const KEYBOARD_BINDINGS: readonly KeyboardBinding[] = [
  { code: "ArrowLeft", action: "move-left", repeats: true },
  { code: "KeyA", action: "move-left", repeats: true },
  { code: "ArrowRight", action: "move-right", repeats: true },
  { code: "KeyD", action: "move-right", repeats: true },
  { code: "ArrowDown", action: "soft-drop-start", repeats: true },
  { code: "KeyS", action: "soft-drop-start", repeats: true },
  { code: "Space", action: "hard-drop", repeats: false },
  { code: "ArrowUp", action: "rotate-cw", repeats: false },
  { code: "KeyW", action: "rotate-cw", repeats: false },
  { code: "KeyZ", action: "rotate-ccw", repeats: false },
  { code: "Escape", action: "pause-toggle", repeats: false },
  { code: "KeyP", action: "pause-toggle", repeats: false }
];

/** Converts a keyboard event to a player action when a binding exists. */
export function mapKeyboardEvent(event: KeyboardInputEvent, nowMs: number): PlayerAction | null {
  const binding = findKeyboardBinding(event.code);
  if (!binding) {
    return null;
  }

  if (event.type === "keyup") {
    return binding.action === "soft-drop-start" ? createPlayerAction("soft-drop-stop", nowMs) : null;
  }

  if (event.type !== "keydown" || event.repeat) {
    return null;
  }

  return createPlayerAction(binding.action, nowMs);
}

/** Attaches keyboard listeners to a target. */
export function attachKeyboardInput(
  target: Window,
  dispatch: (action: PlayerAction) => void
): KeyboardInputSubscription {
  const activeCodes = new Set<string>();
  const repeatTimers = new Map<string, KeyboardRepeatTimer>();

  const reset = (): void => {
    const shouldStopSoftDrop = hasActiveSoftDrop(activeCodes);
    for (const code of repeatTimers.keys()) {
      clearRepeatTimer(target, code, repeatTimers);
    }
    activeCodes.clear();
    if (shouldStopSoftDrop) {
      dispatch(createPlayerAction("soft-drop-stop", nowMs(target)));
    }
  };

  const handleKeyDown = (event: KeyboardEvent): void => {
    const binding = findKeyboardBinding(event.code);
    if (!binding) {
      return;
    }

    event.preventDefault();
    if (event.repeat || activeCodes.has(event.code)) {
      return;
    }

    const softDropWasActive = hasActiveSoftDrop(activeCodes);
    activeCodes.add(event.code);

    if (binding.action === "soft-drop-start" && softDropWasActive) {
      return;
    }

    dispatch(createPlayerAction(binding.action, nowMs(target)));
    if (isHorizontalMove(binding.action)) {
      scheduleHorizontalRepeat(target, event.code, binding.action, dispatch, repeatTimers);
    }
  };

  const handleKeyUp = (event: KeyboardEvent): void => {
    const binding = findKeyboardBinding(event.code);
    if (!binding) {
      return;
    }

    event.preventDefault();
    if (!activeCodes.delete(event.code)) {
      return;
    }

    clearRepeatTimer(target, event.code, repeatTimers);
    if (binding.action === "soft-drop-start" && !hasActiveSoftDrop(activeCodes)) {
      dispatch(createPlayerAction("soft-drop-stop", nowMs(target)));
    }
  };

  target.addEventListener("keydown", handleKeyDown);
  target.addEventListener("keyup", handleKeyUp);

  return {
    reset,
    dispose(): void {
      target.removeEventListener("keydown", handleKeyDown);
      target.removeEventListener("keyup", handleKeyUp);
      reset();
    }
  };
}

interface KeyboardRepeatTimer {
  timeoutId: number;
  intervalId: number | null;
}

function findKeyboardBinding(code: string): KeyboardBinding | null {
  return KEYBOARD_BINDINGS.find((candidate) => candidate.code === code) ?? null;
}

function hasActiveSoftDrop(activeCodes: ReadonlySet<string>): boolean {
  for (const code of activeCodes) {
    const binding = findKeyboardBinding(code);
    if (binding?.action === "soft-drop-start") {
      return true;
    }
  }
  return false;
}

function isHorizontalMove(action: DiscretePlayerActionType): action is "move-left" | "move-right" {
  return action === "move-left" || action === "move-right";
}

function scheduleHorizontalRepeat(
  target: Window,
  code: string,
  action: "move-left" | "move-right",
  dispatch: (action: PlayerAction) => void,
  repeatTimers: Map<string, KeyboardRepeatTimer>
): void {
  const timer: KeyboardRepeatTimer = {
    timeoutId: target.setTimeout(() => {
      dispatch(createPlayerAction(action, nowMs(target)));
      timer.intervalId = target.setInterval(() => {
        dispatch(createPlayerAction(action, nowMs(target)));
      }, INPUT_REPEAT_TIMING.arrMs);
    }, INPUT_REPEAT_TIMING.dasMs),
    intervalId: null
  };
  repeatTimers.set(code, timer);
}

function clearRepeatTimer(
  target: Window,
  code: string,
  repeatTimers: Map<string, KeyboardRepeatTimer>
): void {
  const timer = repeatTimers.get(code);
  if (!timer) {
    return;
  }

  target.clearTimeout(timer.timeoutId);
  if (timer.intervalId !== null) {
    target.clearInterval(timer.intervalId);
  }
  repeatTimers.delete(code);
}

function nowMs(target: Window): number {
  return target.performance.now();
}
