/**
 * Defines input repeat timing used by keyboard adapters and soft-drop cadence.
 */

/** DAS/ARR timing values locked by the UX spec. */
export interface InputRepeatTiming {
  readonly dasMs: number;
  readonly arrMs: number;
}

export const INPUT_REPEAT_TIMING: InputRepeatTiming = {
  dasMs: 167,
  arrMs: 33
};
