/**
 * Defines the headless game engine contract used by the app and Phase 11 harness.
 */
import type { HorizontalDragAction, HorizontalDragEndAction, PlayerAction } from "./actions";
import {
  canPlacePiece,
  clearFullLines,
  createEmptyBoard,
  lockPieceToBoard,
  type Board
} from "./board";
import { TIMING_CONSTANTS } from "./constants";
import { advanceGravity, type GravityState } from "./gravity";
import { serializeGameState, type GameState, type SerializableGameState } from "./game-state";
import { createActivePiece, getActivePieceCells, type ActivePiece } from "./pieces";
import { createSevenBagRandomizer, type PieceRandomizer } from "./randomizer";
import { tryRotatePiece, type RotationDirection } from "./rotation";
import { applyScoringEvent, createInitialScoreState, type LineClearEvent } from "./scoring";

/** Configuration for starting a deterministic game session. */
export interface GameConfig {
  readonly seed: string;
  readonly startingLevel: number;
  readonly ghostEnabled: boolean;
  readonly nextPieceCount: 1 | 3;
  readonly initialBoard?: Board;
}

/** Headless game engine instance. */
export interface GameEngine {
  readonly id: string;
}

interface InternalGameEngine extends GameEngine {
  state: GameState;
  randomizer: PieceRandomizer;
  gravity: GravityState;
  inputQueue: PlayerAction[];
  softDropActive: boolean;
  softDropElapsedMs: number;
  lockDelayElapsedMs: number;
  lockResets: number;
  softDropCellsForPiece: number;
  hardDropCellsForPiece: number;
  lockedDuringActionProcessing: boolean;
  horizontalDrag: HorizontalDragState | null;
}

interface HorizontalDragState {
  readonly gestureId: number;
  readonly startCol: number;
}

let nextEngineId = 1;

/** Creates a new headless game session. */
export function initGame(config: GameConfig): GameEngine {
  const startingLevel = normalizeLevel(config.startingLevel);
  const randomizer = createSevenBagRandomizer(config.seed);
  const engine: InternalGameEngine = {
    id: `game-${nextEngineId}`,
    state: {
      phase: "ready",
      board: config.initialBoard ?? createEmptyBoard(),
      activePiece: null,
      ghostPiece: null,
      nextQueue: randomizer.peek(config.nextPieceCount),
      score: createInitialScoreState(startingLevel),
      settings: {
        ghostEnabled: config.ghostEnabled,
        nextPieceCount: config.nextPieceCount
      },
      lastLock: null,
      gameOverReason: null
    },
    randomizer,
    gravity: {
      level: startingLevel,
      elapsedSinceDropMs: 0
    },
    inputQueue: [],
    softDropActive: false,
    softDropElapsedMs: 0,
    lockDelayElapsedMs: 0,
    lockResets: 0,
    softDropCellsForPiece: 0,
    hardDropCellsForPiece: 0,
    lockedDuringActionProcessing: false,
    horizontalDrag: null
  };

  nextEngineId += 1;
  spawnNextPiece(engine);
  return engine;
}

/** Injects one player action into the engine input queue. */
export function injectInput(engine: GameEngine, action: PlayerAction): GameEngine {
  const internal = asInternalEngine(engine);
  internal.inputQueue.push(action);
  return internal;
}

/** Advances the game by elapsed wall-clock milliseconds. */
export function tick(engine: GameEngine, elapsedMs: number): GameEngine {
  const internal = asInternalEngine(engine);
  const normalizedElapsedMs = Math.max(0, elapsedMs);
  internal.lockedDuringActionProcessing = false;
  // lastLock is a one-frame render/audio event; avoid allocating a fresh
  // state object on idle ticks after it has been consumed.
  if (internal.state.lastLock !== null) {
    updateState(internal, { lastLock: null });
  }

  processQueuedActions(internal);
  if (internal.state.phase === "playing") {
    advanceTimers(internal, normalizedElapsedMs);
  }

  // Piece-mutating helpers refresh derived state. Idle RAF ticks skip
  // ghost/drop-distance recomputation.
  return internal;
}

/** Returns a serializable state snapshot for rendering and tests. */
export function getState(engine: GameEngine): SerializableGameState {
  return serializeGameState(asInternalEngine(engine).state);
}

function asInternalEngine(engine: GameEngine): InternalGameEngine {
  const candidate = engine as Partial<InternalGameEngine>;
  if (candidate.state === undefined || candidate.randomizer === undefined) {
    throw new TypeError("Unknown game engine instance");
  }

  return candidate as InternalGameEngine;
}

function processQueuedActions(engine: InternalGameEngine): void {
  const actions = engine.inputQueue.splice(0);

  for (const action of actions) {
    if (engine.state.phase !== "playing" || engine.state.activePiece === null) {
      continue;
    }

    switch (action.type) {
      case "move-left":
        engine.horizontalDrag = null;
        attemptHorizontalMove(engine, -1);
        break;
      case "move-right":
        engine.horizontalDrag = null;
        attemptHorizontalMove(engine, 1);
        break;
      case "horizontal-drag":
        applyHorizontalDrag(engine, action);
        break;
      case "horizontal-drag-end":
        endHorizontalDrag(engine, action);
        break;
      case "rotate-cw":
        engine.horizontalDrag = null;
        attemptRotation(engine, "cw");
        break;
      case "rotate-ccw":
        engine.horizontalDrag = null;
        attemptRotation(engine, "ccw");
        break;
      case "soft-drop-start":
        engine.softDropActive = true;
        performSoftDropStep(engine);
        break;
      case "soft-drop-stop":
        engine.softDropActive = false;
        engine.softDropElapsedMs = 0;
        break;
      case "hard-drop":
        engine.horizontalDrag = null;
        performHardDrop(engine);
        break;
      case "pause-toggle":
      case "restart":
      case "menu-back":
        break;
    }

    if (engine.lockedDuringActionProcessing) {
      engine.inputQueue.splice(0);
      break;
    }
  }
}

function advanceTimers(engine: InternalGameEngine, elapsedMs: number): void {
  if (engine.state.activePiece === null) {
    return;
  }

  if (isGrounded(engine)) {
    engine.lockDelayElapsedMs += elapsedMs;
    if (engine.lockDelayElapsedMs >= TIMING_CONSTANTS.lockDelayMs) {
      lockActivePiece(engine);
      return;
    }
  } else {
    engine.lockDelayElapsedMs = 0;
  }

  advanceSoftDrop(engine, elapsedMs);
  if (engine.state.phase !== "playing" || engine.state.activePiece === null) {
    return;
  }

  const gravity = advanceGravity(engine.gravity, elapsedMs);
  engine.gravity = gravity.state;

  if (gravity.rowsToDrop > 0 && isGrounded(engine) && engine.lockResets >= TIMING_CONSTANTS.lockDelayResetCap) {
    lockActivePiece(engine);
    return;
  }

  for (let row = 0; row < gravity.rowsToDrop; row += 1) {
    if (engine.state.activePiece === null) {
      return;
    }

    if (!attemptMoveDown(engine)) {
      break;
    }
  }

  if (engine.state.activePiece !== null && !isGrounded(engine)) {
    engine.lockDelayElapsedMs = 0;
  }
}

function advanceSoftDrop(engine: InternalGameEngine, elapsedMs: number): void {
  if (!engine.softDropActive || elapsedMs <= 0 || engine.state.activePiece === null) {
    return;
  }

  engine.softDropElapsedMs += elapsedMs;
  while (engine.softDropElapsedMs >= TIMING_CONSTANTS.arrMs && engine.state.activePiece !== null) {
    engine.softDropElapsedMs -= TIMING_CONSTANTS.arrMs;
    if (!performSoftDropStep(engine)) {
      break;
    }
  }
}

function attemptHorizontalMove(engine: InternalGameEngine, deltaCol: -1 | 1): boolean {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return false;
  }

  const candidate: ActivePiece = {
    ...activePiece,
    origin: {
      col: activePiece.origin.col + deltaCol,
      row: activePiece.origin.row
    }
  };

  if (!canPlacePiece(engine.state.board, candidate)) {
    return false;
  }

  updateActivePiece(engine, candidate);
  resetLockDelayAfterSuccessfulAdjustment(engine);
  return true;
}

function applyHorizontalDrag(engine: InternalGameEngine, action: HorizontalDragAction): void {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return;
  }

  if (!engine.horizontalDrag || engine.horizontalDrag.gestureId !== action.gestureId) {
    engine.horizontalDrag = {
      gestureId: action.gestureId,
      startCol: activePiece.origin.col
    };
  }

  const targetCol = engine.horizontalDrag.startCol + action.offsetColumns;
  while (engine.state.activePiece !== null && engine.state.activePiece.origin.col !== targetCol) {
    const deltaCol = engine.state.activePiece.origin.col < targetCol ? 1 : -1;
    if (!attemptHorizontalMove(engine, deltaCol)) {
      break;
    }
  }
}

function endHorizontalDrag(engine: InternalGameEngine, action: HorizontalDragEndAction): void {
  if (engine.horizontalDrag?.gestureId === action.gestureId) {
    engine.horizontalDrag = null;
  }
}

function attemptRotation(engine: InternalGameEngine, direction: RotationDirection): boolean {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return false;
  }

  const attempt = tryRotatePiece(engine.state.board, activePiece, direction);
  if (!attempt.accepted) {
    return false;
  }

  updateActivePiece(engine, attempt.piece);
  resetLockDelayAfterSuccessfulAdjustment(engine);
  return true;
}

function performSoftDropStep(engine: InternalGameEngine): boolean {
  const moved = attemptMoveDown(engine);
  if (moved) {
    engine.softDropCellsForPiece += 1;
  }

  return moved;
}

function performHardDrop(engine: InternalGameEngine): void {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return;
  }

  const distance = getDropDistance(engine.state.board, activePiece);
  const droppedPiece: ActivePiece = {
    ...activePiece,
    origin: {
      col: activePiece.origin.col,
      row: activePiece.origin.row + distance
    }
  };
  engine.hardDropCellsForPiece += distance;
  updateActivePiece(engine, droppedPiece);
  lockActivePiece(engine);
}

function attemptMoveDown(engine: InternalGameEngine): boolean {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return false;
  }

  const candidate: ActivePiece = {
    ...activePiece,
    origin: {
      col: activePiece.origin.col,
      row: activePiece.origin.row + 1
    }
  };

  if (!canPlacePiece(engine.state.board, candidate)) {
    return false;
  }

  updateActivePiece(engine, candidate);
  if (!isGrounded(engine)) {
    engine.lockDelayElapsedMs = 0;
  }

  return true;
}

function lockActivePiece(engine: InternalGameEngine): void {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return;
  }

  const lockedBoard = lockPieceToBoard(engine.state.board, activePiece);
  const locksEntirelyInBuffer = getActivePieceCells(activePiece).every((point) => point.row < lockedBoard.bufferRows);

  if (locksEntirelyInBuffer) {
    updateState(engine, {
      phase: "game-over",
      board: lockedBoard,
      activePiece: null,
      ghostPiece: null,
      lastLock: {
        piece: activePiece.kind,
        clearedLines: 0,
        clearedRows: [],
        awardedPoints: 0
      },
      gameOverReason: "lock-out"
    });
    engine.lockedDuringActionProcessing = true;
    return;
  }

  const clearResult = clearFullLines(lockedBoard);
  const clearedLines = toClearedLineCount(clearResult.clearedRows.length);
  const scoreEvent: LineClearEvent = {
    clearedLines,
    softDropCells: engine.softDropCellsForPiece,
    hardDropCells: engine.hardDropCellsForPiece
  };
  const scoreResult = applyScoringEvent(engine.state.score, scoreEvent);

  updateState(engine, {
    board: clearResult.board,
    score: scoreResult.state,
    activePiece: null,
    ghostPiece: null,
    lastLock: {
      piece: activePiece.kind,
      clearedLines,
      clearedRows: clearResult.clearedRows,
      awardedPoints: scoreResult.awardedPoints
    }
  });
  engine.lockedDuringActionProcessing = true;
  spawnNextPiece(engine);
}

function spawnNextPiece(engine: InternalGameEngine): void {
  const [kind] = engine.randomizer.draw();
  const activePiece = createActivePiece(kind);
  const nextQueue = engine.randomizer.peek(engine.state.settings.nextPieceCount);
  const canSpawn = canPlacePiece(engine.state.board, activePiece);

  engine.gravity = {
    level: engine.state.score.level,
    elapsedSinceDropMs: 0
  };
  engine.softDropActive = false;
  engine.softDropElapsedMs = 0;
  engine.lockDelayElapsedMs = 0;
  engine.lockResets = 0;
  engine.softDropCellsForPiece = 0;
  engine.hardDropCellsForPiece = 0;
  engine.horizontalDrag = null;

  if (!canSpawn) {
    updateState(engine, {
      phase: "game-over",
      activePiece,
      ghostPiece: null,
      nextQueue,
      gameOverReason: "block-out"
    });
    return;
  }

  updateState(engine, {
    phase: "playing",
    activePiece,
    nextQueue,
    gameOverReason: null
  });
  refreshDerivedState(engine);
}

function updateActivePiece(engine: InternalGameEngine, activePiece: ActivePiece): void {
  updateState(engine, { activePiece });
  refreshDerivedState(engine);
}

function refreshDerivedState(engine: InternalGameEngine): void {
  const activePiece = engine.state.activePiece;
  const ghostPiece =
    engine.state.phase === "playing" && activePiece !== null
      ? computeGhostPiece(engine.state.board, activePiece, engine.state.settings.ghostEnabled)
      : null;

  updateState(engine, {
    ghostPiece,
    nextQueue: engine.randomizer.peek(engine.state.settings.nextPieceCount)
  });
}

function computeGhostPiece(board: Board, activePiece: ActivePiece, ghostEnabled: boolean): ActivePiece | null {
  if (!ghostEnabled) {
    return null;
  }

  return {
    ...activePiece,
    origin: {
      col: activePiece.origin.col,
      row: activePiece.origin.row + getDropDistance(board, activePiece)
    }
  };
}

function getDropDistance(board: Board, activePiece: ActivePiece): number {
  let distance = 0;
  let candidate: ActivePiece = activePiece;

  while (true) {
    const nextCandidate: ActivePiece = {
      ...candidate,
      origin: {
        col: candidate.origin.col,
        row: candidate.origin.row + 1
      }
    };

    if (!canPlacePiece(board, nextCandidate)) {
      return distance;
    }

    distance += 1;
    candidate = nextCandidate;
  }
}

// Grounded status only needs a one-row collision test; full drop-distance scans
// are reserved for ghost and hard drop.
function isGrounded(engine: InternalGameEngine): boolean {
  const activePiece = engine.state.activePiece;
  if (activePiece === null) {
    return false;
  }

  return !canPlacePiece(engine.state.board, {
    ...activePiece,
    origin: {
      col: activePiece.origin.col,
      row: activePiece.origin.row + 1
    }
  });
}

function resetLockDelayAfterSuccessfulAdjustment(engine: InternalGameEngine): void {
  if (!isGrounded(engine)) {
    engine.lockDelayElapsedMs = 0;
    return;
  }

  if (engine.lockResets < TIMING_CONSTANTS.lockDelayResetCap) {
    engine.lockDelayElapsedMs = 0;
    engine.lockResets += 1;
  }
}

function updateState(engine: InternalGameEngine, patch: Partial<GameState>): void {
  engine.state = {
    ...engine.state,
    ...patch
  };
}

function toClearedLineCount(count: number): 0 | 1 | 2 | 3 | 4 {
  if (count < 0 || count > 4) {
    throw new RangeError(`A single Tetris piece cannot clear ${count} lines`);
  }

  return count as 0 | 1 | 2 | 3 | 4;
}

function normalizeLevel(level: number): number {
  return Number.isFinite(level) ? Math.max(1, Math.trunc(level)) : 1;
}
