/**
 * Defines player actions shared by input adapters, game logic, and the test harness.
 */

/** Discrete named actions the game engine can consume without extra payload. */
export type DiscretePlayerActionType =
  | "move-left"
  | "move-right"
  | "soft-drop-start"
  | "soft-drop-stop"
  | "hard-drop"
  | "rotate-cw"
  | "rotate-ccw"
  | "pause-toggle"
  | "restart"
  | "menu-back";

/** Named actions the game engine can consume. */
export type PlayerActionType = DiscretePlayerActionType | "horizontal-drag" | "horizontal-drag-end";

/** A timestamped discrete player action for deterministic orchestration. */
export interface DiscretePlayerAction {
  readonly type: DiscretePlayerActionType;
  readonly occurredAtMs: number;
}

/** A live horizontal drag target rounded to whole board columns. */
export interface HorizontalDragAction {
  readonly type: "horizontal-drag";
  readonly occurredAtMs: number;
  readonly gestureId: number;
  readonly offsetColumns: number;
}

/** Ends or cancels a live horizontal drag gesture. */
export interface HorizontalDragEndAction {
  readonly type: "horizontal-drag-end";
  readonly occurredAtMs: number;
  readonly gestureId: number;
}

/** A timestamped player action for deterministic orchestration. */
export type PlayerAction = DiscretePlayerAction | HorizontalDragAction | HorizontalDragEndAction;

/** Creates a timestamped discrete player action. */
export function createPlayerAction(type: DiscretePlayerActionType, occurredAtMs: number): DiscretePlayerAction {
  return { type, occurredAtMs };
}

/** Creates a live horizontal drag action. */
export function createHorizontalDragAction(
  gestureId: number,
  offsetColumns: number,
  occurredAtMs: number
): HorizontalDragAction {
  return { type: "horizontal-drag", gestureId, offsetColumns, occurredAtMs };
}

/** Creates an action that ends a live horizontal drag. */
export function createHorizontalDragEndAction(gestureId: number, occurredAtMs: number): HorizontalDragEndAction {
  return { type: "horizontal-drag-end", gestureId, occurredAtMs };
}
